function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2200)}
function go(route){state.route=route;const routeRole={review:'expert',approval:'owner',certification:'committee'};state.role=routeRole[route]||(['overview','operations'].includes(route)?state.role:'admin');location.hash=route;render();window.scrollTo({top:0,behavior:'auto'})}
function markDone(id){if(!state.completed.includes(id))state.completed.push(id)}
function badge(status){const cls=status.includes('已')||status.includes('通过')||status.includes('正式')?'ok':status.includes('异常')||status.includes('驳回')?'bad':status.includes('待')||status.includes('构建')?'warn':'info';return `<span class="status ${cls}">${status}</span>`}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`}
function context(){return ''}
function renderShell(){
  const navButton=(id,label,icon,sub=false,badgeText='')=>`<button class="nav-item ${sub?'nav-subitem':''} ${state.route===id?'active':''}" data-route="${id}"><span class="nav-icon">${icon}</span><span class="nav-label">${label}</span>${badgeText?`<span class="nav-badge">${badgeText}</span>`:''}</button>`;
  const intakeNavButton=(mode,label,icon)=>`<button class="nav-item nav-subitem ${state.route==='intake'&&state.intakeTab===mode?'active':''}" data-intake-route="${mode}"><span class="nav-icon">${icon}</span><span class="nav-label">${label}</span></button>`;
  const navCluster=(label,icon,routes,items)=>`<div class="nav-cluster ${routes.includes(state.route)?'open':''}"><div class="nav-parent"><span class="nav-icon">${icon}</span><span>${label}</span><i>⌄</i></div><div class="nav-children">${items.join('')}</div></div>`;
  $('#main-nav').innerHTML=`<div class="nav-group-label">首页</div>${navButton('overview','知识底座首页','⌂')}<div class="nav-group-label">知识工程</div>${navCluster('知识接入','↗',['intake'],[intakeNavButton('integration','知识集成','↗'),intakeNavButton('set','知识集构建','▤')])}${navCluster('知识加工','◇',['parse','extract'],[navButton('parse','多模态解析','◫',true),navButton('extract','知识抽取','◇',true)])}${navCluster('知识审核与认证','◎',['review','approval','certification'],[navButton('review','知识审核','✓',true,'12'),navButton('approval','知识审批','◉',true),navButton('certification','知识认证','◎',true)])}${navCluster('知识服务','⌁',['storage','service'],[navButton('storage','知识入库','▤',true),navButton('service','检索服务构建','⌁',true)])}<div class="nav-group-label nav-ops-label">知识运营</div>${navButton('operations','运营看板','▦')}`;
  $('#stage-strip').style.display=['overview','operations'].includes(state.route)?'none':'flex';
  $('#stage-strip').innerHTML=stages.map((s,i)=>`<button class="stage-chip ${(state.route===s.id||(state.route==='storage'&&s.id==='service'))?'active':''} ${state.completed.includes(s.id)?'done':''}" data-route="${s.id}"><span class="num">${state.completed.includes(s.id)?'✓':i+1}</span><span>${s.label}</span></button>`).join('');
  const role=roles.find(r=>r.id===state.role);$('#role-name').textContent=role.name;$('#role-avatar').textContent=role.short;
  $('#role-menu').innerHTML=roles.map(r=>`<div class="role-option" data-role="${r.id}"><span class="avatar">${r.short}</span><span><b>${r.name}</b><p>${r.desc}</p></span></div>`).join('');
  const currentDomain=domain();$('#top-domain-name').textContent=currentDomain.name;$('#top-domain-badge').textContent=currentDomain.icon;$('#top-domain-badge').style.background=currentDomain.color;
  $('#domain-menu').innerHTML=domains.map(d=>`<button class="domain-option ${d.id===state.domain?'active':''}" data-domain="${d.id}"><span style="--domain:${d.color}">${d.icon}</span><b>${d.name}</b><small>${d.services} 个知识服务</small></button>`).join('');
  const pageSection=state.route==='overview'?'首页':state.route==='operations'?'知识运营':'知识工程';
  $('#page-section').textContent=pageSection;
  $('#page-crumb').textContent=state.route==='intake'?(state.intakeTab==='set'?'知识集构建':'知识集成'):(navItems.find(x=>x.id===state.route)?.label||'知识底座首页');
}
function overview(){return `${pageHead('KNOWLEDGE FOUNDATION','首页','从领域入口进入独立知识旅程；每个领域拥有自己的知识资产、知识服务与治理进度。','<button class="btn" data-route="operations">查看运营数据</button>')}
  <section class="domain-grid">${domains.map(d=>`<button class="domain-card ${d.id===state.domain?'selected':''}" data-domain="${d.id}" style="--domain:${d.color}"><div class="domain-card-head"><span class="domain-badge">${d.icon}</span></div><h3>${d.name}</h3><p>${d.desc}</p><div class="domain-numbers"><span><b>${d.org}</b><small>组织知识资产</small></span><span><b>${d.team}</b><small>团队知识资产</small></span><span><b>${d.services}</b><small>知识服务</small></span></div><div class="domain-progress"><i style="width:${d.progress}%"></i></div><footer><b>进入管理流程 →</b></footer></button>`).join('')}</section>
  <div class="card journey journey-home"><div class="card-title"><div><h3>知识底座旅程概览</h3><p>将领域数据转化为可检索、可复用的业务知识服务</p></div></div><div class="journey-flow">${stages.map(s=>`<div class="journey-node ${state.completed.includes(s.id)?'done':''}" data-route="${s.id}"><div class="orb">${s.icon}</div><b>${s.label}</b><small>${s.hint}</small></div>`).join('')}</div><div class="value-flow"><span><i>1</i><b>原始数据</b><small>结构化 / 非结构化</small></span><em>→</em><span><i>2</i><b>智能处理</b><small>AI 提取 / 映射生成</small></span><em>→</em><span><i>3</i><b>向量和图谱</b><small>语义向量 / 实体 / 关系</small></span><em>→</em><span><i>4</i><b>业务价值</b><small>精确检索 / 语义检索 / 知识可溯源 / 知识自演进</small></span></div></div>`}
function legacyIntake(){const d=domain();return `${context()}${pageHead('STAGE 01 · 领域知识管理员','知识接入与场景打标',`在“${d.name}”领域内接入公开文档，按场景标签组合形成特定文档集。`,'<button class="btn">接入日志</button><button class="btn primary" data-action="upload">＋ 上传文档</button>')}
  <div class="source-cards">${[['公','公司公开文档','已同步'],['3M','3MS','已同步'],['iL','iLearning / Wiki','已同步'],['＋','本地经验材料','可上传']].map((x,i)=>`<div class="source-card ${i<3?'on':''}"><span class="source-logo">${x[0]}</span><span><b>${x[1]}</b><small>${x[2]}</small></span></div>`).join('')}</div>
  <div class="upload-zone" data-action="upload"><span class="upload-icon">⇧</span><span><b>上传或拖入多模态文档</b><small>支持 PDF、Office、图片、邮件和音视频；系统自动识别元数据</small></span><span class="status info">单文件 ≤ 50MB</span></div>
  <div class="panel" style="margin-top:15px"><div class="panel-head"><h3>${d.name}文档库</h3><button class="btn primary small" data-action="create-set">将已选文档建为文档集</button></div><div class="filter-bar">${[['责任中心','区域TOB'],['业务域',d.name],['对象',d.object],['主题',d.topic],['适用区域',d.region]].map(x=>`<div class="filter-group"><span class="filter-label">${x[0]}</span><button class="tag active">${x[1]} ×</button></div>`).join('')}</div><div class="batch-bar"><span>✓ 已选择 ${state.selectedDocs.size} 个文档</span><span>标签组合命中 12 个文档</span><button class="btn small" data-action="apply-tags">批量打标签</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th></th><th>文档</th><th>来源</th><th>责任中心</th><th>业务域</th><th>对象</th><th>主题</th><th>适用区域</th><th>状态</th></tr></thead><tbody>${demoDocs.map(x=>`<tr class="${state.selectedDocs.has(x.id)?'selected':''}"><td><input class="doc-check" data-id="${x.id}" type="checkbox" ${state.selectedDocs.has(x.id)?'checked':''}></td><td><div class="doc-title"><span class="file-icon">${x.type}</span><span><b>${x.name}</b><small>${x.owner}</small></span></div></td><td>${x.source}</td><td>${x.tags[0]}</td><td>${d.name}</td><td>${d.object}</td><td>${d.topic}</td><td>${d.region}</td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table></div></div><div class="action-bar"><span class="notice">标签可任意组合筛选；每个文档集可在后续阶段配置不同抽取字段。</span><span class="spacer"></span><button class="btn primary" data-action="finish-intake">保存文档集并进入解析 →</button></div>`}
function parse(){return `${context()}${pageHead('STAGE 02 · 系统自动化','多模态解析与质量准入','统一解析文本、表格、图表、图片和音视频，并在抽取前完成质量检查。','<button class="btn">质量规则</button><button class="btn primary" data-action="run-parse">▶ 执行解析</button>')}<div class="grid cols-3"><div class="card metric"><small>解析队列</small><strong>12</strong><span class="status warn">3 处理中</span></div><div class="card metric"><small>格式覆盖</small><strong>8</strong><span class="status info">文本 / 表格 / 音视频</span></div><div class="card card-pad"><div class="card-title"><h3>平均质量</h3><b>91</b></div>${[['文本完整性',97],['表格识别率',89],['业务相关度',93]].map(x=>`<div class="qbar"><span>${x[0]}</span><span class="bar"><i style="width:${x[1]}%"></i></span><b>${x[1]}</b></div>`).join('')}</div></div><div class="panel" style="margin-top:15px"><div class="panel-head"><h3>解析明细 · ${domain().scene}</h3><span class="status info">准入阈值 ≥ 80</span></div><table class="data-table"><thead><tr><th>文档</th><th>识别内容</th><th>进度</th><th>质量分</th><th>业务相关度</th><th>准入状态</th><th></th></tr></thead><tbody>${demoDocs.map((x,i)=>`<tr><td><b>${x.name}</b></td><td>${['文本 34 · 表格 8 · 图表 6','文本 18 · 表格 3','工作表 6 · 关系 24','文本 22 · 图表 9'][i]}</td><td>${x.quality}%</td><td>${x.quality}</td><td>${[95,92,89,76][i]}%</td><td>${badge(i===3?'需人工确认':'已准入')}</td><td><button class="btn small" data-action="preview-parse">预览</button></td></tr>`).join('')}</tbody></table></div><div class="action-bar"><span class="spacer"></span><button class="btn primary" data-action="finish-parse">确认准入并配置抽取 →</button></div>`}
function extract(){const set=docSets.find(x=>x.id===state.selectedSet);return `${context()}${pageHead('STAGE 03 · 领域知识管理员','按文档集抽取领域知识','先维护领域知识结构，再为不同标签组合的文档集配置差异化抽取字段。','<button class="btn">规则版本 V3</button><button class="btn primary" data-action="run-extract">运行抽取</button>')}<div class="process-strip"><div class="process-step done"><span>✓</span><div><b>维护知识结构</b><small>定义对象、场景与属性</small></div></div><div class="process-step active"><span>2</span><div><b>绑定文档集与字段</b><small>各文档集独立配置</small></div></div><div class="process-step"><span>3</span><div><b>抽取并消歧</b><small>生成结构化知识</small></div></div></div><div class="panel architecture-card"><div class="panel-head"><h3>${domain().name} · ${domain().scene}知识结构</h3><span class="status ok">已启用</span></div><div class="panel-body definition-grid">${[['对象',domain().object],['场景',domain().scene],['对象关系','归属 / 影响 / 驱动'],['指标度量','数值 / 口径 / 周期'],['策略与规则','阈值 / 触发逻辑'],['行动建议','角色 / 动作 / 时效']].map(x=>`<div class="definition-item"><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}</div></div><div class="schema-layout"><div class="panel"><div class="panel-head"><h3>文档集</h3></div><div class="set-list">${docSets.map(s=>`<div class="set-item ${s.id===set.id?'active':''}" data-set="${s.id}"><b>${s.name}</b><p>${domain().name} + ${domain().object} + ${domain().topic}</p><small>${s.count} 份文档 · ${s.model}</small></div>`).join('')}</div></div><div class="panel field-board"><div class="panel-head"><div><h3>${set.name}</h3><small>目标模型：${set.model}</small></div><button class="btn small" data-action="copy-schema">复制配置</button></div><div class="panel-body"><div class="notice">本配置仅作用于当前文档集；切换文档集可看到不同字段。</div><div class="field-group" style="margin-top:18px"><div class="field-group-title">自动继承的场景标签</div><div class="field-list">${['责任中心','业务域','对象','主题','适用区域'].map(x=>`<span class="field-chip required"><i></i>${x}</span>`).join('')}</div></div><div class="field-group"><div class="field-group-title">${set.model}专属字段</div><div class="field-list">${state.fields[set.id].map(x=>`<span class="field-chip custom"><i></i>${x}<button class="remove" data-action="remove-field" data-field="${x}">×</button></span>`).join('')}<button class="add-field" data-action="add-field">＋ 添加字段</button></div></div><div class="action-bar"><span class="status ok">已自动保存</span><span class="spacer"></span><button class="btn primary" data-action="finish-extract">生成结构化知识 →</button></div></div></div></div>`}
function fieldSourceOptions(source){return ['文档自身标签','场景标签','自动抽取','用户填写'].map(x=>`<option ${x===source?'selected':''}>${x}</option>`).join('')}
function fieldTypeOptions(type){return ['枚举','文本'].map(x=>`<option ${x===(type==='长文本'?'文本':type)?'selected':''}>${x}</option>`).join('')}
function fieldResultBadge(source){return source==='自动抽取'?'<span class="status info">智能抽取</span>':source==='用户填写'?'<span class="status warn">任务内填写默认值</span>':'<span class="status ok">随文档自动带出</span>'}
function modelFieldTable(model){return `<div class="table-wrap"><table class="data-table model-field-table"><thead><tr><th>字段名称</th><th>字段类型</th><th>取值方式</th><th>标签映射 / 抽取要求 / 枚举值</th><th>结果处理</th><th>操作</th></tr></thead><tbody>${model.fields.map((f,i)=>`<tr><td><b>${f[0]}</b></td><td><select>${fieldTypeOptions(f[1])}</select></td><td><select>${fieldSourceOptions(f[2])}</select></td><td>${f[1]==='枚举'?`<div class="enum-cell"><span>${f[3]}</span><button class="btn small" data-action="config-enum-values" data-field="${f[0]}">枚举值配置</button></div>`:`<input value="${f[3]}">`}</td><td>${fieldResultBadge(f[2])}</td><td><button class="btn small" data-action="edit-model-field" data-field-index="${i}">编辑</button></td></tr>`).join('')}</tbody></table></div>`}
function taskSetCard(set){const selected=state.taskSets.has(set.id);const d=domain();return `<div class="task-set-card ${selected?'selected':''}"><label class="task-set-head"><input class="task-set-check" data-id="${set.id}" type="checkbox" ${selected?'checked':''}><span><b>${set.name}</b><small>${set.count} 条知识 · 默认模型：${set.model}</small></span><span class="status ${selected?'ok':''}">${selected?'已选择':'未选择'}</span></label>${selected?`<div class="task-tag-filter"><small>标签筛选</small>${[['责任中心','财经'],['业务域',d.name],['对象',d.object],['主题',d.topic],['适用区域',d.region]].map(x=>`<label><span>${x[0]}</span><select><option>${x[1]}</option><option>全部</option></select></label>`).join('')}</div>`:''}</div>`}
function extractV2(){const model=knowledgeModels.find(x=>x.id===state.selectedModel);return `${context()}${pageHead('STAGE 03 · 领域知识管理员','知识结构与抽取任务','通过多张知识模型表定义知识结构，再创建任务选择一个或多个知识集执行抽取。','<button class="btn" data-action="create-model">＋ 新建知识模型</button><button class="btn primary" data-action="run-extract-task">运行抽取任务</button>')}<div class="process-strip"><div class="process-step done"><span>✓</span><div><b>维护知识结构</b><small>一张表代表一个知识模型</small></div></div><div class="process-step active"><span>2</span><div><b>创建抽取任务</b><small>多选知识集并按标签筛选</small></div></div><div class="process-step"><span>3</span><div><b>抽取并消歧</b><small>自动带出标签并生成知识</small></div></div></div><div class="notice extraction-guide"><b>字段取值规则：</b>文档自身标签和场景标签直接复用，抽取结果会自动带出文档对应标签；其他非文档标签字段由系统自动抽取。</div><div class="model-selector">${knowledgeModels.map(x=>`<button class="model-card ${x.id===model.id?'active':''}" data-model="${x.id}"><span class="model-table-icon">▦</span><span><b>${x.name}</b><small>${x.desc}</small></span><em>${x.fields.length} 个字段</em></button>`).join('')}</div><div class="panel model-editor"><div class="panel-head"><div><h3>${model.name} · 知识模型表</h3><small>一张表定义一种知识结构；字段可复用标签或配置自动抽取</small></div><div><button class="btn small" data-action="add-model-field">＋ 添加字段</button><button class="btn primary small" data-action="save-model">保存结构</button></div></div><div class="source-legend"><span class="status ok">场景标签 / 文档自身标签：自动带出</span><span class="status info">其他字段：自动抽取</span></div>${modelFieldTable(model)}</div><div class="panel extract-task-panel"><div class="panel-head"><div><h3>创建抽取任务</h3><small>任务编号 T-20261013-01 · 可选择一个或多个知识集</small></div><span class="status warn">配置中</span></div><div class="panel-body"><div class="form-grid task-basic"><div class="form-field"><label>任务名称</label><input value="经营领域知识抽取任务"></div><div class="form-field"><label>关联知识模型</label><select multiple><option selected>预警规则</option><option selected>改进策略</option><option>归因关系</option></select></div></div><div class="task-section-title"><span><b>选择知识集</b><small>已选择 ${state.taskSets.size} 个；每个知识集可独立配置标签筛选范围</small></span></div><div class="task-set-list">${docSets.map(taskSetCard).join('')}</div><div class="action-bar"><span class="notice">任务运行时仅处理所选知识集中满足标签条件的知识文档。</span><span class="spacer"></span><button class="btn" data-action="save-extract-task">保存任务</button><button class="btn primary" data-action="run-extract-task">保存并运行</button></div></div></div>`}
function taskDocumentTable(){return `<div class="extract-doc-toolbar"><div class="form-field"><label>来源知识集</label><select><option>${domain().name}知识集</option><option>${domain().scene}专题知识集</option></select></div><div class="search"><span>⌕</span><input placeholder="搜索知识标题或内容"></div><div class="task-doc-tags">${['责任中心：区域TOB','业务域：'+domain().name,'适用区域：中国区'].map(x=>`<button>${x} ×</button>`).join('')}</div><button class="btn small" data-action="add-task-docs">＋ 从知识集添加文档</button></div><div class="table-wrap"><table class="data-table extract-doc-table"><thead><tr><th></th><th>知识文档</th><th>来源</th><th>责任中心</th><th>业务域</th><th>对象</th><th>主题</th><th>适用区域</th><th>质量</th></tr></thead><tbody>${demoDocs.map((x,i)=>`<tr class="${state.extractDocs.has(x.id)?'selected':''}"><td><input class="extract-doc-check" data-id="${x.id}" type="checkbox" ${state.extractDocs.has(x.id)?'checked':''}></td><td><div class="doc-title"><span class="file-icon compact">${x.type}</span><span><b>${x.name}</b><small>${x.owner}</small></span></div></td><td>${x.source}</td><td>${x.tags[0]}</td><td>${domain().name}</td><td>${i===2?'经营单元':'渠道'}</td><td>${i===3?'库存周转':domain().topic}</td><td>${domain().region}</td><td><span class="confidence">${x.quality}</span></td></tr>`).join('')}</tbody></table></div><div class="task-doc-footer"><span>已选择 <b>${state.extractDocs.size}</b> 个文档，只有选中文档会进入本次抽取任务</span><button class="btn small" data-action="clear-task-docs">清空选择</button></div>`}
function taskModelCards(){return `<div class="task-model-grid">${knowledgeModels.map(x=>`<label class="task-model-option ${state.taskModels.has(x.id)?'selected':''}"><input class="task-model-check" data-id="${x.id}" type="checkbox" ${state.taskModels.has(x.id)?'checked':''}><span class="model-table-icon">▦</span><span><b>${x.name}</b><small>${x.desc}</small></span><em>${x.fields.length} 个字段</em></label>`).join('')}</div>`}
function taskUserFillFields(){const fields=[];knowledgeModels.filter(m=>state.taskModels.has(m.id)).forEach(m=>m.fields.filter(f=>f[2]==='用户填写').forEach(f=>{if(!fields.some(x=>x[0]===f[0]))fields.push(f)}));return `<div class="user-fill-note"><span>✎</span><div><b>批次默认值</b><small>以下值将写入本任务选中的 ${state.extractDocs.size} 个文档；未填写字段保持为空，可在专家审核时补齐。</small></div></div><div class="user-fill-grid">${fields.map((f,i)=>`<div class="form-field"><label>${f[0]} <em>${f[1]} · 用户填写</em></label>${f[1]==='枚举'?`<select><option value="">不填写（保持为空）</option>${(sceneEnumOptions[f[0]]||f[3].split(' / ')).map((x,j)=>`<option ${((f[0]==='责任中心'&&j===1)||(f[0]==='业务域'&&j===0))?'selected':''}>${x}</option>`).join('')}</select>`:`<input placeholder="可选填；未填写则抽取结果为空">`}<small>${f[1]==='枚举'?'取值来自知识结构的枚举值配置':'文本将作为该批文档的统一默认值'}</small></div>`).join('')}</div>${fields.length?'':'<div class="notice">所选知识结构暂未配置“用户填写”字段。</div>'}`}
function extractV3(){const model=knowledgeModels.find(x=>x.id===state.selectedModel);return `${context()}${pageHead('STAGE 03 · 领域知识管理员','知识结构与抽取任务','先定义字段取值方式，再从知识集中筛选具体文档，为该批文档选择知识结构并配置用户填写字段。','<button class="btn" data-action="create-model">＋ 新建知识模型</button><button class="btn primary" data-action="run-extract-task">运行抽取任务</button>')}<div class="process-strip extract-process"><div class="process-step done"><span>✓</span><div><b>维护知识结构</b><small>字段类型与取值方式</small></div></div><div class="process-step active"><span>2</span><div><b>选择任务文档</b><small>知识集筛选 / 手动添加</small></div></div><div class="process-step active"><span>3</span><div><b>配置知识结构</b><small>结构多选 / 批次默认值</small></div></div><div class="process-step"><span>4</span><div><b>抽取并消歧</b><small>生成结构化知识</small></div></div></div><div class="notice extraction-guide"><b>字段取值规则：</b>文档自身标签和场景标签随文档带出；自动抽取字段由系统识别；用户填写字段在任务中统一配置，未填写时抽取结果保持为空。</div><div class="model-selector">${knowledgeModels.map(x=>`<button class="model-card ${x.id===model.id?'active':''}" data-model="${x.id}"><span class="model-table-icon">▦</span><span><b>${x.name}</b><small>${x.desc}</small></span><em>${x.fields.length} 个字段</em></button>`).join('')}</div><div class="panel model-editor"><div class="panel-head"><div><h3>${model.name} · 知识模型表</h3><small>字段类型支持枚举或文本；取值方式支持文档标签、场景标签、自动抽取和用户填写</small></div><div><button class="btn small" data-action="add-model-field">＋ 添加字段</button><button class="btn primary small" data-action="save-model">保存结构</button></div></div><div class="source-legend"><span class="status ok">标签：随文档带出</span><span class="status info">自动抽取：系统识别</span><span class="status warn">用户填写：任务级默认值</span></div>${modelFieldTable(model)}</div><div class="panel extract-task-panel"><div class="panel-head"><div><h3>创建抽取任务</h3><small>任务编号 T-20261013-01 · 精确选择本次处理的文档与知识结构</small></div><span class="status warn">配置中</span></div><div class="panel-body"><div class="form-grid task-basic"><div class="form-field"><label>任务名称</label><input value="${domain().name}领域知识抽取任务"></div><div class="form-field"><label>任务说明</label><input value="按已选文档批量生成预警规则和改进策略"></div></div><div class="task-section-title"><span><b>01 · 从知识集中选择文档</b><small>可按标签筛选，也可手动添加特定文档</small></span><strong>${state.extractDocs.size} 个已选</strong></div>${taskDocumentTable()}<div class="task-section-title"><span><b>02 · 配置待抽取的知识结构</b><small>同一批文档可同时抽取为多个知识结构</small></span><strong>${state.taskModels.size} 个已选</strong></div>${taskModelCards()}<div class="task-section-title"><span><b>03 · 配置用户填写字段</b><small>对本批文档统一赋值，留空字段不会自动生成内容</small></span></div>${taskUserFillFields()}<div class="task-impact-summary"><span><small>任务文档</small><b>${state.extractDocs.size}</b></span><i>×</i><span><small>知识结构</small><b>${state.taskModels.size}</b></span><i>→</i><span><small>预计抽取结果</small><b>${state.extractDocs.size*state.taskModels.size}</b></span><p>用户填写值将作为这批文档对应字段的默认值写入结果。</p></div><div class="action-bar"><span class="notice">未填写的用户字段将保持为空，不影响任务运行，可在知识审核阶段补齐。</span><span class="spacer"></span><button class="btn" data-action="save-extract-task">保存任务</button><button class="btn primary" data-action="run-extract-task">保存并运行</button></div></div></div>`}
function review(){const r=records.find(x=>x.id===state.selectedRecord);return `${context()}${pageHead('STAGE 04 · 领域知识专家','专家确认抽取结果','领域知识专家逐条核对证据、修订字段，也可放弃或人工补录知识。','<button class="btn" data-action="add-record">＋ 补录知识</button><button class="btn primary" data-action="batch-confirm">批量确认高置信结果</button>')}<div class="review-layout"><div class="panel"><div class="panel-head"><h3>待确认知识</h3>${badge('12 条')}</div><div class="record-list">${records.map(x=>`<div class="record ${x.id===r.id?'active':''}" data-record="${x.id}"><div class="record-top"><b>${x.title}</b><span class="confidence">${x.confidence}%</span></div><p>${x.type} · ${x.status}</p></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h3>${r.title}</h3>${badge(r.status)}</div><div class="panel-body"><div class="form-grid">${[['知识类型',r.type],['预警指标',r.indicator],['规则逻辑',r.logic],['阈值条件',r.threshold],['适用范围',`${domain().region} / ${domain().object}`],['处置建议',r.advice]].map((x,i)=>`<div class="form-field ${i===5?'full':''}"><label>${x[0]}</label>${i===5?`<textarea>${x[1]}</textarea>`:`<input value="${esc(x[1])}">`}</div>`).join('')}</div><div class="evidence" style="margin-top:14px"><b>来源证据：</b>经营分析报告第 18 页。<mark>销售收入环比下降达到 15% 时触发黄色预警</mark>。抽取规则 V3，置信度 ${r.confidence}%。</div><div class="action-bar"><button class="btn danger" data-action="drop-record">放弃</button><span class="spacer"></span><button class="btn" data-action="save-record">保存修改</button><button class="btn success" data-action="confirm-record">确认知识</button></div></div></div></div><div class="action-bar"><span class="spacer"></span><button class="btn primary" data-action="submit-approval">提交审批与认证 →</button></div>`}
function approval(){return `${context()}${pageHead('STAGE 05 · 责任人 / 专委会','审批与知识认证','责任人判断知识是否可用，领域专委会最终定性是否成为组织级知识。','')}<div class="approval-flow"><div class="approval-step done"><span class="step-no">✓</span><h3>知识专家提交</h3><p>确认、修订并说明来源证据。</p><div class="approval-meta"><span>王璐 · 今天 10:42</span><span>12 条知识</span></div></div><div class="approval-arrow">→</div><div class="approval-step ${state.approved?'done':'active'}"><span class="step-no">${state.approved?'✓':'2'}</span><h3>领域知识责任人审批</h3><p>判断内容准确性、范围和可用性。</p><div class="approval-meta"><span>陈思远</span><span>${state.approved?'已通过':'待处理'}</span></div>${!state.approved?'<div class="action-bar"><button class="btn danger small" data-action="reject-owner">驳回</button><button class="btn success small" data-action="approve-owner">通过</button></div>':''}</div><div class="approval-arrow">→</div><div class="approval-step ${state.certified?'done':state.approved?'active':''}"><span class="step-no">${state.certified?'✓':'3'}</span><h3>领域专委会定性</h3><p>判断能否成为跨团队复用的组织级知识。</p><div class="approval-meta"><span>${domain().owner}</span><span>${state.certified?'组织级知识':state.approved?'待定性':'等待审批'}</span></div>${state.approved&&!state.certified?'<div class="action-bar"><button class="btn small" data-action="domain-only">仅领域知识</button><button class="btn primary small" data-action="certify">认证组织级</button></div>':''}</div></div><div class="panel" style="margin-top:15px"><div class="panel-head"><h3>知识包摘要</h3>${badge(state.certified?'已认证':state.approved?'待定性':'待审批')}</div><div class="panel-body grid cols-3"><div class="metric"><small>知识条目</small><strong>12</strong><span class="status ok">完整率 100%</span></div><div class="metric"><small>平均置信度</small><strong>93%</strong><span class="status ok">质量通过</span></div><div class="metric"><small>预计服务</small><strong>3</strong><span class="status info">可构建模式</span></div></div></div>${state.certified?'<div class="action-bar"><span class="spacer"></span><button class="btn primary" data-route="service">构建知识服务 →</button></div>':''}`}
function service(){const t=serviceTypes[state.serviceMode];return `${context()}${pageHead('STAGE 06 · 领域知识管理员 / IT','正式入库与知识服务构建','审批后的知识在此生成正式版本，并按消费需求构建语义、精确或混合检索服务。',`<button class="btn">版本历史</button><button class="btn primary" data-action="publish-service">${state.published?'服务已发布':'构建并发布'}</button>`)}<div class="service-modes">${Object.entries(serviceTypes).map(([id,x])=>`<button class="service-mode ${id===state.serviceMode?'active':''}" data-mode="${id}"><span class="service-icon">${x.icon}</span><span class="status ${id==='hybrid'?'ok':'info'}">${x.tag}${id==='hybrid'?' · 推荐':''}</span><h3>${x.name}</h3><p>${x.desc}</p><footer>${x.steps.join(' → ')}</footer></button>`).join('')}</div><div class="service-layout"><div class="panel"><div class="panel-head"><div><h3>${t.name}配置</h3><small>${t.tag}</small></div>${badge(state.published?'正式服务':state.built?'已构建':'待构建')}</div><div class="panel-body"><div class="form-grid"><div class="form-field"><label>正式知识版本</label><select><option>${domain().scene}知识包 V1.0 · 12 条</option></select></div><div class="form-field"><label>服务名称</label><input value="${domain().name}-${domain().scene}-${t.name}"></div><div class="form-field"><label>对象与场景过滤</label><input value="${domain().object} / ${domain().scene} / ${domain().region}"></div><div class="form-field"><label>更新策略</label><select><option>知识版本发布后自动增量更新</option></select></div></div><div class="pipeline"><div class="pipeline-node done"><span>✓</span><b>正式知识入库</b><small>V1.0 · 可追溯</small></div><i>→</i>${t.steps.map((x,i)=>`<div class="pipeline-node ${state.built?'done':i===0?'active':''}"><span>${state.built?'✓':i+2}</span><b>${x}</b><small>${state.built?'完成':'待执行'}</small></div>${i<t.steps.length-1?'<i>→</i>':''}`).join('')}<i>→</i><div class="pipeline-node ${state.published?'done':''}"><span>${state.published?'✓':'◎'}</span><b>服务发布</b><small>API / MCP</small></div></div><div class="endpoint"><span><small>调用地址</small><code>${t.endpoint}</code></span><button class="btn small" data-action="copy-endpoint">复制</button></div></div></div><div class="panel"><div class="panel-head"><h3>检索效果预览</h3><span class="status info">${t.tag}</span></div><div class="panel-body"><div class="preview-query">${state.serviceMode==='graph'?'对象=渠道业绩 AND 阈值≥15%':'收入下降多少需要预警？'}<button class="btn primary small" data-action="test-service">测试</button></div><div class="result-card"><div><span class="status ok">命中 0.96</span><b>渠道销售收入环比降幅预警</b></div><p>本期销售收入环比下降 ≥ 15% 时触发黄色预警，下钻客户与产品线定位损失来源。</p><footer>来源：Q3 经营分析报告第 18 页 · 组织级知识 V1.0</footer></div><div class="service-facts">${[['检索路径',state.serviceMode==='hybrid'?'语义召回 + 图谱精排':state.serviceMode==='slice'?'向量语义召回':'图谱条件匹配'],['预计知识量','12 条'],['证据可追溯','100%'],['消费方式','API / MCP / Agent']].map(x=>`<span><small>${x[0]}</small><b>${x[1]}</b></span>`).join('')}</div></div></div></div>`}
function operations(){return `${pageHead('OPERATIONS','知识运营看板','跨领域观察知识资产、旅程效率、服务运行和反馈闭环；不打断领域内生产流程。','<button class="btn">导出周报</button><button class="btn primary">运营配置</button>')}<div class="grid cols-4">${[['领域知识','860','本月 +74'],['组织级知识','642','认证率 74.7%'],['知识服务','15','运行中 13'],['近 30 天调用','26,840','↑ 18.6%']].map((x,i)=>`<div class="card metric"><small>${x[0]}</small><strong>${x[1]}</strong><span class="${i===2?'status warn':'delta'}">${x[2]}</span></div>`).join('')}</div><div class="ops-grid"><div class="panel"><div class="panel-head"><h3>各领域资产与服务</h3><span class="status info">近 30 天</span></div><div class="panel-body ops-bars">${domains.map(d=>`<div class="bar-row"><span class="bar-label"><i style="background:${d.color}"></i>${d.name}</span><span class="bar-track"><i style="width:${d.org/3.5}%;background:${d.color}"></i></span><b>${d.org}</b><small>${d.services} 个服务</small></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h3>旅程转化</h3><span class="status ok">整体健康</span></div><div class="panel-body funnel">${[['接入文档','381','100%'],['准入文档','342','89.8%'],['抽取知识','1,124','—'],['专家确认','968','86.1%'],['审批通过','860','88.8%'],['服务可用','15','13 运行中']].map((x,i)=>`<div style="--w:${100-i*8}%"><span>${i+1}</span><b>${x[0]}</b><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div></div></div><div class="panel" style="margin-top:15px"><div class="panel-head"><h3>知识服务运行状态</h3><span class="status ok">总体可用性 99.92%</span></div><table class="data-table"><thead><tr><th>领域</th><th>服务</th><th>模式</th><th>知识版本</th><th>今日调用</th><th>命中率</th><th>P95 延迟</th><th>状态</th></tr></thead><tbody>${[['智能分析','收入经营知识服务','混合模式','V1.3','2,486','91.6%','182 ms','运行中'],['合同管理','条款风险检索','知识图谱','V2.1','1,208','96.2%','96 ms','运行中'],['项目管理','交付经验问答','知识切片','V1.0','864','84.7%','214 ms','运行中'],['客户经营','商机转化助手','混合模式','V0.9','326','79.1%','238 ms','待优化']].map(x=>`<tr>${x.slice(0,7).map((v,i)=>`<td>${i===1?'<b>'+v+'</b>':v}</td>`).join('')}<td>${badge(x[7])}</td></tr>`).join('')}</tbody></table></div>`}
function pipelineCard(p){return `<div class="pipeline-card"><span class="source-logo">${p.icon}</span><span><b>${p.name}</b><small>${p.scope}</small></span><span class="status ok">${p.status}</span><button class="btn small" data-action="view-pipeline" data-pipeline="${p.name}">查看</button><span class="lock">🔒</span></div>`}
function integrationPanel(){
  if(state.integrationMode==='offline')return `<div class="panel"><div class="panel-head"><div><h3>离线上传知识</h3><small>共 ${offlineKnowledge.length} 条 · 创建知识表单时上传源文档</small></div><button class="btn primary small" data-action="new-offline">＋ 创建知识表单</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>知识标题</th><th>知识内容</th><th>类型</th><th>自定义标签</th><th>创建人</th><th>创建时间</th><th>操作</th></tr></thead><tbody>${offlineKnowledge.map(x=>`<tr><td><b>${x.title}</b></td><td class="knowledge-content">${x.content}</td><td><span class="file-icon compact">${x.type}</span></td><td><div class="tag-row">${x.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div></td><td>${x.creator}</td><td>${x.time}</td><td><button class="btn small" data-action="edit-offline" data-id="${x.id}">编辑</button><button class="btn small danger" data-action="delete-offline" data-id="${x.id}">删除</button></td></tr>`).join('')}</tbody></table></div></div>`;
  return `<div class="notice pipeline-notice">系统集成管道由平台内置，仅支持查看，用户不可编辑或删除。</div><div class="pipeline-groups"><section><div class="section-title"><span>通用知识管道</span><small>5 条 · 全员可见</small></div><div class="pipeline-grid">${knowledgePipelines.filter(x=>x.scope==='通用知识管道').map(p=>pipelineCard(p)).join('')}</div></section><section><div class="section-title"><span>有使用权限的管道</span><small>3 条 · 按授权范围可见</small></div><div class="pipeline-grid">${knowledgePipelines.filter(x=>x.scope==='权限知识管道').map(p=>pipelineCard(p)).join('')}</div></section></div>`;
}
function knowledgeMemberTable(){return `<div class="table-wrap"><table class="data-table knowledge-member-table"><thead><tr><th></th><th><div class="column-filter"><b>知识标题</b><label><span>⌕</span><input data-knowledge-filter="title" placeholder="搜索标题"></label></div></th><th><div class="column-filter"><b>来源</b><select data-knowledge-filter="source"><option value="">全部来源</option><option>知识圈</option><option>离线上传</option></select></div></th><th>类型</th><th>添加方式</th><th>质量分</th><th>场景标签</th><th>操作</th></tr></thead><tbody>${offlineKnowledge.map((x,i)=>{const source=i%2?'离线上传':'知识圈';return `<tr class="${state.selectedKnowledge.has(x.id)?'selected':''}" data-knowledge-title="${x.title}" data-knowledge-source="${source}"><td><input class="knowledge-check" data-id="${x.id}" type="checkbox" ${state.selectedKnowledge.has(x.id)?'checked':''}></td><td><b>${x.title}</b></td><td>${source}</td><td>${x.type}</td><td>${i<2?'<span class="status info">规则自动</span>':'<span class="status">手动添加</span>'}</td><td><span class="confidence">${[96,92,88,84][i]}</span></td><td><div class="tag-row">${x.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div></td><td><button class="btn small" data-action="tag-one" data-id="${x.id}">打标签</button><button class="btn small danger" data-action="remove-one" data-id="${x.id}">移除</button></td></tr>`}).join('')}</tbody></table><div class="knowledge-filter-empty">没有符合筛选条件的知识</div></div>`}
function pipelineFilterRule(name){
  const fields=name==='知识圈'?[['圈子名称','经营管理、PFC知识地图'],['发布时间','近 3 年']]:name==='3MS'?[['责任部门','集团财经'],['文档类型','案例'],['专业领域','经营管理'],['发布时间','近 3 年']]:[['关键词','包含当前领域关键词'],['发布时间','近 3 年']];
  return `<div class="pipeline-rule-block" data-pipeline-rule="${name}"><div class="pipeline-rule-head"><span><small>知识管道</small><b>${name}</b></span><button type="button" class="btn small danger remove-pipeline-rule">移除</button></div><div class="pipeline-rule-fields">${fields.map(x=>`<div class="form-field"><label>${x[0]}</label><select><option>${x[1]}</option></select></div>`).join('')}</div></div>`
}
function setBuildPanel(){const d=domain();return `<div class="set-workbench"><aside class="panel set-sidebar"><div class="panel-head"><h3>知识集</h3><button class="btn small" data-action="create-knowledge-set">＋ 创建</button></div><div class="set-list"><div class="set-item active"><b>智能分析知识集</b><p>自动规则 + 手动维护</p><small>26 条知识 · 今日新增 3 条</small></div><div class="set-item"><b>客户经营知识集</b><p>专题筛选规则</p><small>12 条知识</small></div></div></aside><div><div class="rule-grid"><div class="rule-card ${state.autoRule?'enabled':''}"><div><span class="rule-icon">⌕</span><b>自动添加筛选规则</b><small>按规则将系统管道或上传知识自动加入知识集</small></div><span class="status ${state.autoRule?'ok':'warn'}">${state.autoRule?'已配置':'未配置'}</span><p>来源：全部可用管道　类型：PDF / Word / XLS　关键词：${d.topic}</p><button class="btn small" data-action="config-auto-rule">配置规则</button></div><div class="rule-card ${state.qualityRule?'enabled':''}"><div><span class="rule-icon">✓</span><b>质量过滤规则</b><small>检查完整性、重复度、时效性与业务相关度</small></div><span class="status ${state.qualityRule?'ok':'warn'}">${state.qualityRule?'已配置':'未配置'}</span><p>质量分 ≥ 80　重复度 ≤ 15%　必须包含来源与创建人</p><button class="btn small" data-action="config-quality-rule">配置规则</button></div></div><div class="schedule-bar"><span class="schedule-icon">◷</span><span><b>自动任务：每日 00:00</b><small>执行知识自动添加及质量检查 · 下次运行：明天 00:00</small></span><span class="status ok">已启用</span><button class="btn small" data-action="run-schedule">立即运行</button></div><div class="panel" style="margin-top:15px"><div class="panel-head"><div><h3>智能分析知识集内容</h3><small>可在表头搜索知识标题、筛选来源，并进行手动添加、批量移除和批量打标签</small></div><div class="set-actions"><button class="btn small" data-action="manual-add">手动添加</button></div></div>${knowledgeMemberTable()}<div class="batch-footer"><span>已选择 ${state.selectedKnowledge.size} 条知识</span><span class="spacer"></span><button class="btn danger small" data-action="remove-knowledge">从知识集移除</button><button class="btn primary small" data-action="go-tagging">批量打标签</button></div></div></div></div>`}
function taggingPanel(){const d=domain();return `<div class="tagging-layout"><div class="panel"><div class="panel-head"><div><h3>场景化标签体系</h3><small>标签随当前领域和知识场景继承</small></div><button class="btn small" data-action="manage-tags">标签管理</button></div><div class="panel-body tag-dimensions">${[['责任中心',['财经','区域经营','共享中心']],['业务域',[d.name,d.scene]],['对象',[d.object,'经营单元','指标']],['主题',[d.topic,'风险预警','复盘改进']],['适用区域',[d.region,'亚太区','全球']]].map(x=>`<div><b>${x[0]}</b><span>${x[1].map((t,i)=>`<button class="tag ${i===0?'active':''}">${t}</button>`).join('')}</span></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><h3>待打标签知识</h3><small>可选择单条或多条知识批量应用标签</small></div><span class="status info">已选 ${state.selectedKnowledge.size} 条</span></div>${knowledgeMemberTable()}<div class="batch-footer"><span class="notice">当前将应用：责任中心 / 业务域 / 对象 / 主题 / 适用区域</span><span class="spacer"></span><button class="btn primary" data-action="save-tags">应用到所选知识</button></div></div></div>`}
function intake(){const d=domain();const tabs=[['integration','知识集成','系统集成与离线上传'],['set','知识集构建','自动规则与手动添加'],['tagging','知识打标签','场景标签与批量操作']];return `${context()}${pageHead('STAGE 01 · 领域知识管理员','知识接入',`在“${d.name}”领域完成知识集成、知识集构建与场景化打标。`,'<button class="btn">接入日志</button>')}<div class="intake-tabs">${tabs.map((x,i)=>`<button class="intake-tab ${state.intakeTab===x[0]?'active':''}" data-intake-tab="${x[0]}"><span>${i+1}</span><b>${x[1]}</b><small>${x[2]}</small></button>`).join('')}</div>${state.intakeTab==='integration'?`<div class="integration-switch"><button class="${state.integrationMode==='system'?'active':''}" data-integration-mode="system">系统集成 <small>8 条管道</small></button><button class="${state.integrationMode==='offline'?'active':''}" data-integration-mode="offline">离线上传 <small>多格式文档</small></button></div>${integrationPanel()}`:state.intakeTab==='set'?setBuildPanel():taggingPanel()}<div class="action-bar"><span class="notice">知识集每日 00:00 自动执行规则添加与质量检查，所有变更均记录操作日志。</span><span class="spacer"></span><button class="btn primary" data-action="finish-intake">完成知识接入并进入解析 →</button></div>`}

function renderPage(){const map={overview:overviewV3,intake:intakeV4,parse:parseV3,extract:extractV3,review:reviewV3,approval:approvalV4,certification:certificationV3,storage:storageV2,service:retrievalServiceV2,operations};$('#page').innerHTML=(map[state.route]||overviewV3)();if(state.route==='intake'&&state.intakeTab==='set'){const p=document.querySelectorAll('.rule-card p');if(p[0])p[0].textContent='已配置 2 个管道：知识圈（圈子名称、发布时间）· 3MS（责任部门、文档类型、专业领域、发布时间）';if(p[1])p[1].textContent='规则 + AI：全文字数 > 500；5 个标签维度至少命中 3 个枚举维度'}}
function render(){renderShell();renderPage();bindDynamic()}
function bindDynamic(){
  document.querySelectorAll('[data-route]').forEach(x=>x.onclick=()=>go(x.dataset.route));
  document.querySelectorAll('[data-intake-tab]').forEach(x=>x.onclick=()=>{state.intakeTab=x.dataset.intakeTab;render()});
  document.querySelectorAll('[data-intake-route]').forEach(x=>x.onclick=()=>{state.route='intake';state.role='admin';state.intakeTab=x.dataset.intakeRoute;location.hash='intake';render();window.scrollTo({top:0,behavior:'auto'})});
  document.querySelectorAll('[data-integration-mode]').forEach(x=>x.onclick=()=>{state.integrationMode=x.dataset.integrationMode;render()});
  document.querySelectorAll('[data-domain]').forEach(x=>x.onclick=()=>{state.domain=x.dataset.domain;$('#domain-switcher')?.classList.remove('open');syncDomainSamples();state.completed=[];state.approved=false;state.certified=false;state.knowledgeMode='undecided';state.rawPackageCertified=false;state.structuredPackageCertified=false;state.built=false;state.published=false;go('intake')});
  document.querySelectorAll('[data-mode]').forEach(x=>x.onclick=()=>{state.serviceMode=x.dataset.mode;state.built=false;state.published=false;render()});
  document.querySelectorAll('[data-consumption-source]').forEach(x=>x.onclick=()=>{if(x.disabled)return;state.consumptionSource=x.dataset.consumptionSource;state.built=false;state.published=false;render()});
  document.querySelectorAll('[data-model]').forEach(x=>x.onclick=()=>{state.selectedModel=x.dataset.model;render()});
  document.querySelectorAll('[data-review-model]').forEach(x=>x.onclick=()=>{state.reviewModel=x.dataset.reviewModel;state.reviewRecord=(reviewResults[state.reviewModel]||[])[0]?.id;render()});
  document.querySelectorAll('[data-review-scope]').forEach(x=>x.onclick=()=>{state.reviewScope=x.dataset.reviewScope;render()});
  document.querySelectorAll('[data-approval-scope]').forEach(x=>x.onclick=()=>{state.approvalScope=x.dataset.approvalScope;render()});
  document.querySelectorAll('[data-certification-scope]').forEach(x=>x.onclick=()=>{state.certificationScope=x.dataset.certificationScope;render()});
  document.querySelectorAll('[data-review-result]').forEach(x=>x.onclick=()=>openReviewRecordDialog(x.dataset.reviewResult));
  document.querySelectorAll('[data-work-item]').forEach(x=>x.onclick=()=>{const stage=x.dataset.workStage,id=x.dataset.workItem,type=x.dataset.workType;if(stage==='review'){state.reviewWorkItem=id;state.reviewScope=type}else if(stage==='approval'){state.approvalWorkItem=id;state.approvalScope=type}else{state.certificationWorkItem=id;state.certificationScope=type}render();window.scrollTo({top:0,behavior:'auto'})});
  document.querySelectorAll('[data-review-filter]').forEach(x=>{x.oninput=applyReviewFilters;x.onchange=applyReviewFilters});
  document.querySelectorAll('.audit-filter-chip').forEach(x=>x.onclick=()=>x.classList.toggle('active'));
  document.querySelectorAll('[data-filter-mode]').forEach(x=>x.onclick=()=>{const select=document.getElementById(x.dataset.filterTarget);if(!select)return;x.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===x));select.multiple=x.dataset.filterMode==='multi';if(!select.multiple&&select.selectedOptions.length>1)select.value=select.selectedOptions[0]?.value||'';applyReviewFilters()});
  document.querySelectorAll('[data-set]').forEach(x=>x.onclick=()=>{state.selectedSet=x.dataset.set;render()});
  document.querySelectorAll('[data-record]').forEach(x=>x.onclick=()=>{state.selectedRecord=x.dataset.record;render()});
  document.querySelectorAll('.doc-check').forEach(x=>x.onchange=()=>{const id=+x.dataset.id;x.checked?state.selectedDocs.add(id):state.selectedDocs.delete(id);render()});
  document.querySelectorAll('.knowledge-check').forEach(x=>x.onchange=()=>{const id=+x.dataset.id;x.checked?state.selectedKnowledge.add(id):state.selectedKnowledge.delete(id);render()});
  document.querySelectorAll('[data-knowledge-filter]').forEach(x=>{x.oninput=applyKnowledgeMemberFilters;x.onchange=applyKnowledgeMemberFilters});
  document.querySelectorAll('.task-set-check').forEach(x=>x.onchange=()=>{x.checked?state.taskSets.add(x.dataset.id):state.taskSets.delete(x.dataset.id);render()});
  document.querySelectorAll('.extract-doc-check').forEach(x=>x.onchange=()=>{const id=+x.dataset.id;x.checked?state.extractDocs.add(id):state.extractDocs.delete(id);render()});
  document.querySelectorAll('.task-model-check').forEach(x=>x.onchange=()=>{x.checked?state.taskModels.add(x.dataset.id):state.taskModels.delete(x.dataset.id);render()});
  document.querySelectorAll('.knowledge-base-check').forEach(x=>x.onchange=()=>{x.checked?state.selectedBases.add(x.dataset.id):state.selectedBases.delete(x.dataset.id);render()});
  document.querySelectorAll('[data-action]').forEach(x=>x.onclick=e=>handleAction(x.dataset.action,x,e));
}
function modal(title,body,confirm='完成',onConfirm){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>${title}</h3><button class="modal-close" data-close>×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn" data-close>取消</button><button class="btn primary" id="modal-confirm">${confirm}</button></div></div></div>`;document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);$('#modal-confirm').onclick=()=>{onConfirm?.();closeModal()}}
function closeModal(){$('#modal-root').innerHTML=''}
function openKnowledgeBaseDialog(){modal('新增知识库',`<div class="base-builder"><div class="notice">选择知识库类型，并从已认证的原始知识包或结构化知识包中选择一个或多个消费知识集。</div><div class="base-type-grid"><label class="active"><input type="radio" name="base-type" value="vector" checked><span>≋</span><div><b>向量库</b><small>面向语义向量化、相似度召回和自然语言检索</small></div></label><label><input type="radio" name="base-type" value="graph"><span>⌘</span><div><b>知识图谱</b><small>面向实体、属性、关系和规则的图谱化入库</small></div></label></div><div class="form-field"><label>知识库名称</label><input value="${domain().name}领域知识库"></div><div class="base-source-sets"><b>消费知识集（可多选）</b><label><input type="checkbox" checked><span><strong>原始知识包 V1.0</strong><small>原始知识 / 文档 · 已认证</small></span></label><label><input type="checkbox" checked><span><strong>结构化知识包 V1.0</strong><small>抽取后知识 · 已认证</small></span></label></div><div class="base-build-steps" data-base-steps="vector"><b>向量库构建入库步骤</b><div>${['锁定知识版本','内容切片','向量化','向量索引','质量验证','发布'].map((x,i)=>`<span><i>${i+1}</i>${x}</span>`).join('')}</div></div><div class="base-build-steps" data-base-steps="graph" hidden><b>知识图谱构建入库步骤</b><div>${['锁定知识版本','实体映射','关系抽取','图谱校验','图索引','发布'].map((x,i)=>`<span><i>${i+1}</i>${x}</span>`).join('')}</div></div></div>`,'构建并发布',()=>{state.newBaseType=document.querySelector('input[name="base-type"]:checked')?.value||'vector';state.newBasePublished=true;state.selectedBases.add('custom-base');toast('知识库构建完成并已发布，列表记录已生成');render()});const sync=()=>{const value=document.querySelector('input[name="base-type"]:checked')?.value||'vector';document.querySelectorAll('.base-type-grid label').forEach(x=>x.classList.toggle('active',x.querySelector('input').checked));document.querySelectorAll('[data-base-steps]').forEach(x=>x.hidden=x.dataset.baseSteps!==value)};document.querySelectorAll('input[name="base-type"]').forEach(x=>x.onchange=sync);sync()}
function openTagApplyDialog(count){const d=domain();return modal(`为 ${count||1} 条知识打标签`,`<div class="notice">标签选项来自当前知识集的“场景化标签配置”，应用后将记录操作人和变更时间。</div><div class="tag-apply-grid">${[['责任中心',['财经','区域经营','共享中心']],['业务域',[d.name,d.scene]],['对象',[d.object,'经营单元','指标']],['主题',[d.topic,'风险预警','复盘改进']],['适用区域',[d.region,'亚太区','全球']]].map(x=>`<section><b>${x[0]}</b>${x[1].map((t,i)=>`<label><input type="${x[0]==='主题'?'checkbox':'radio'}" name="apply-${x[0]}" ${i===0?'checked':''}>${t}</label>`).join('')}</section>`).join('')}</div>`,'应用标签',()=>toast(`已为 ${count||1} 条知识应用场景标签`))}
function handleAction(a,el){
  if(a==='back-work-queue'){if(state.route==='review')state.reviewWorkItem=null;else if(state.route==='approval')state.approvalWorkItem=null;else state.certificationWorkItem=null;return render()}
  if(a==='create-knowledge-base')return openKnowledgeBaseDialog();
  if(a==='config-scenario-tags')return modal('场景化标签配置',`<div class="notice">维护知识集可用的场景标签及枚举值，下方知识内容的单条和批量打标签均从此处取值。</div><div class="scenario-tag-editor">${[['责任中心','财经、区域经营、共享中心'],['业务域',`${domain().name}、${domain().scene}`],['对象',`${domain().object}、经营单元、指标`],['主题',`${domain().topic}、风险预警、复盘改进`],['适用区域',`${domain().region}、亚太区、全球`]].map(x=>`<label><span>${x[0]}</span><input value="${x[1]}"><button>＋</button></label>`).join('')}</div>`,'保存配置',()=>toast('场景化标签配置已保存'));
  if(a==='configure-audit-view')return modal('页面呈现配置',`<div class="audit-config"><div class="audit-config-intro"><b>配置知识清单的展示方式</b><span>设置仅影响当前领域，可随知识模型保存为页面模板。</span></div><section><div class="audit-config-title"><span><b>01 · 展示列</b><small>拖动可调整顺序</small></span><button>恢复默认</button></div><div class="audit-config-options">${['知识编码','知识名称','责任中心','业务域','对象','主题','适用区域','状态','知识来源'].map((x,i)=>`<label><input type="checkbox" ${i<8?'checked':''}><span class="drag">⋮⋮</span>${x}</label>`).join('')}</div></section><section><div class="audit-config-title"><span><b>02 · 筛选字段</b><small>场景标签支持单选或多选</small></span></div><div class="audit-config-options">${['责任中心','业务域','对象','主题','适用区域','知识名称','状态','创建时间'].map((x,i)=>`<label><input type="checkbox" ${i<6?'checked':''}>${x}${i<5?'<em>多选</em>':''}</label>`).join('')}</div></section><section><div class="audit-config-title"><span><b>03 · 知识目录</b><small>固定三级目录结构与字段映射</small></span></div><div class="directory-mapping"><div><i>L1</i><span><small>责任中心 · 示例：区域TOB</small><b>责任中心</b></span><select><option>映射：责任中心</option></select></div><div><i>L2</i><span><small>业务域 · 示例：政企</small><b>业务域</b></span><select><option>映射：业务域</option></select></div><div><i>L3</i><span><small>对象 · 示例：渠道</small><b>对象</b></span><select><option>映射：对象</option></select></div></div></section></div>`,'保存配置',()=>toast('页面呈现配置已保存'));
  if(a==='toggle-help')return modal('Demo 操作说明','<div class="notice">首页先选择领域，再按 6 个阶段完成领域知识管理。知识服务构建阶段可切换知识切片、知识图谱和混合模式；跨领域统计统一进入运营看板。</div>','知道了');
  if(a==='view-pipeline')return modal(`${el.dataset.pipeline} · 管道详情`,`<div class="notice">该管道由系统内置，仅支持查看，不可编辑或删除。</div><div class="pipeline-detail"><span><small>同步方式</small><b>增量同步</b></span><span><small>运行周期</small><b>每 30 分钟</b></span><span><small>最近同步</small><b>今天 12:30</b></span><span><small>运行状态</small><b>正常</b></span></div>`,'关闭');
  if(a==='new-offline'||a==='edit-offline')return modal(a==='new-offline'?'创建知识表单':'编辑知识表单',`<div class="form-grid">${a==='new-offline'?'<div class="form-field full"><label>上传知识文档</label><input type="file" accept=".txt,.doc,.docx,.pdf,.xls,.xlsx,.ppt,.pptx,.html,.htm,.png"><small>支持 TXT、Word、PDF、XLS、PPT、HTML、PNG；选择文件后可继续完善表单信息</small></div>':''}<div class="form-field"><label>知识标题</label><input value="经营规则说明"></div><div class="form-field"><label>类型</label><select><option>PDF</option><option>Word</option><option>TXT</option></select></div><div class="form-field full"><label>知识内容</label><textarea>请输入知识正文或摘要</textarea></div><div class="form-field full"><label>自定义标签</label><input value="经营, 规则"></div></div>`,'保存',()=>toast('知识表单已保存'));
  if(a==='delete-offline')return modal('删除知识','<div class="notice">删除后该条离线上传知识将不再参与知识集自动添加。</div>','确认删除',()=>toast('知识已删除'));
  if(a==='create-knowledge-set')return modal('创建知识集','<div class="form-field"><label>知识集名称</label><input value="'+domain().name+'知识集"></div><div class="form-field" style="margin-top:12px"><label>知识集说明</label><textarea>沉淀'+domain().name+'领域的规则、指标与最佳实践</textarea></div>','创建',()=>toast('知识集已创建'));
  if(a==='config-auto-rule'){
    modal('配置自动添加筛选规则',`<div class="notice">先选择一个知识管道，再使用该管道集成知识的专属字段配置筛选条件；可添加多个管道。</div><div class="rule-config-toolbar"><div class="form-field"><label>选择知识管道</label><select id="pipeline-rule-selector">${knowledgePipelines.map(p=>`<option>${p.name}</option>`).join('')}</select></div><button type="button" class="btn primary" id="add-pipeline-rule">＋ 添加管道规则</button></div><div class="pipeline-rule-list" id="pipeline-rule-list">${pipelineFilterRule('知识圈')}${pipelineFilterRule('3MS')}</div><div class="notice">所有管道规则将在每日 00:00 分别执行知识自动添加。</div>`,'保存规则',()=>{state.autoRule=true;const count=document.querySelectorAll('.pipeline-rule-block').length;toast(`已保存 ${count} 条管道筛选规则`)});
    const list=$('#pipeline-rule-list');
    const bindRemove=()=>document.querySelectorAll('.remove-pipeline-rule').forEach(x=>x.onclick=()=>x.closest('.pipeline-rule-block').remove());
    $('#add-pipeline-rule').onclick=()=>{const name=$('#pipeline-rule-selector').value;if(list.querySelector(`[data-pipeline-rule="${name}"]`))return toast(`${name} 管道规则已存在`);list.insertAdjacentHTML('beforeend',pipelineFilterRule(name));bindRemove()};
    bindRemove();return
  }
  if(a==='config-quality-rule')return modal('配置质量过滤规则',`<div class="notice">质量检查可组合使用确定性规则与 AI 语义判断；全部启用条件通过后，知识才会自动加入知识集。</div><div class="quality-mode-grid"><section><div class="quality-mode-head"><span><b>规则判断</b><small>按明确条件逐条校验</small></span><span class="status ok">已启用</span></div><label class="quality-rule-item"><input type="checkbox" checked><span><b>全文字数</b><small>知识正文长度必须满足阈值</small></span><span class="inline-condition"><select><option>&gt;</option></select><input value="500"><em>字</em></span></label><label class="quality-rule-item"><input type="checkbox" checked><span><b>场景标签枚举命中</b><small>文本包含责任中心 / 业务域 / 对象 / 主题 / 适用区域的枚举值</small></span><span class="inline-condition"><select><option>至少命中</option></select><input value="3"><em>/ 5 维</em></span></label></section><section><div class="quality-mode-head"><span><b>AI 判断</b><small>识别无法完全规则化的内容质量</small></span><span class="status ok">已启用</span></div><div class="ai-check-list"><label><input type="checkbox" checked> 内容完整性</label><label><input type="checkbox" checked> 业务相关度</label><label><input type="checkbox" checked> 表述清晰度</label><label><input type="checkbox" checked> 时效性风险</label></div><div class="form-field"><label>AI 最低质量分</label><input value="80"></div></section></div><div class="notice">每日 00:00 执行质量检查；未通过的知识进入待处理队列，并记录具体未通过原因。</div>`,'保存规则',()=>{state.qualityRule=true;toast('规则判断与 AI 判断配置已保存')});
  if(a==='run-schedule')return toast('自动添加与质量检查任务已开始运行');
  if(a==='manual-add'){modal('手动添加知识',`<div class="manual-add-filters"><div class="form-field"><label>知识管道</label><select id="manual-pipeline-filter"><option value="">全部管道</option>${knowledgePipelines.map(x=>`<option>${x.name}</option>`).join('')}<option>离线上传</option></select></div><div class="form-field"><label>文本搜索</label><div class="search"><span>⌕</span><input id="manual-text-filter" placeholder="搜索知识标题或内容"></div></div></div><div class="manual-add-results"><label data-pipeline="Wiki" data-search="经营管理规范 指标口径"><input type="checkbox" checked><span><b>经营管理规范与指标口径</b><small>来源：Wiki · 质量分 92</small></span></label><label data-pipeline="知识圈" data-search="智能分析 最佳实践"><input type="checkbox"><span><b>智能分析场景最佳实践</b><small>来源：知识圈 · 质量分 89</small></span></label><label data-pipeline="3MS" data-search="客户经营 分析案例"><input type="checkbox"><span><b>客户经营分析案例</b><small>来源：3MS · 质量分 91</small></span></label><label data-pipeline="离线上传" data-search="经营复盘 模板"><input type="checkbox"><span><b>月度经营复盘模板</b><small>来源：离线上传 · 质量分 88</small></span></label><div class="manual-add-empty">没有符合条件的知识</div></div>`,'添加到知识集',()=>toast('已手动添加所选知识'));const filter=()=>{const pipeline=$('#manual-pipeline-filter')?.value||'',text=($('#manual-text-filter')?.value||'').trim().toLowerCase();let shown=0;document.querySelectorAll('.manual-add-results>label').forEach(x=>{const match=(!pipeline||x.dataset.pipeline===pipeline)&&(!text||x.dataset.search.toLowerCase().includes(text));x.hidden=!match;if(match)shown++});document.querySelector('.manual-add-empty')?.classList.toggle('show',shown===0)};$('#manual-pipeline-filter').onchange=filter;$('#manual-text-filter').oninput=filter;return}
  if(a==='remove-knowledge')return modal('批量移除知识',`<div class="notice">将从当前知识集中移除已选的 ${state.selectedKnowledge.size} 条知识，原始知识不会被删除。</div>`,'确认移除',()=>{state.selectedKnowledge.clear();toast('已从知识集移除')});
  if(a==='remove-one'){state.selectedKnowledge.delete(+el.dataset.id);toast('已从知识集移除该条知识');return render()}
  if(a==='go-tagging')return openTagApplyDialog(state.selectedKnowledge.size);
  if(a==='go-set-build'){state.intakeTab='set';toast('已进入知识集构建');return render()}
  if(a==='tag-one'){state.selectedKnowledge=new Set([+el.dataset.id]);return openTagApplyDialog(1)}
  if(a==='save-tags')return toast(`已为 ${state.selectedKnowledge.size} 条知识应用场景化标签`);
  if(a==='manage-tags')return toast('标签管理在 Demo 中以示意形式呈现');
  if(a==='reset'){state.domain='operation';syncDomainSamples();state.completed=[];state.approved=false;state.certified=false;state.directKnowledgeSet=false;state.dualPath=false;state.knowledgeMode='undecided';state.reviewScope='raw';state.approvalScope='raw';state.certificationScope='raw';state.reviewWorkItem=null;state.approvalWorkItem=null;state.certificationWorkItem=null;state.rawPackageCertified=false;state.structuredPackageCertified=false;state.consumptionSource='structured';state.serviceMode='hybrid';state.built=false;state.published=false;toast('演示状态已重置');return render()}
  if(a==='upload')return modal('上传领域文档','<div class="check-row"><input type="checkbox" checked><span><b>领域材料.pdf</b><small>12.4 MB · 待识别元数据</small></span></div><div class="form-field"><label>归属领域</label><input value="'+domain().name+'"></div>','上传并解析',()=>toast('文档已加入接入队列'));
  if(a==='apply-tags')return toast(`已为 ${state.selectedDocs.size} 份文档应用场景标签`);
  if(a==='create-set')return modal('创建特定文档集','<div class="form-field"><label>文档集名称</label><input value="'+domain().region+' · '+domain().scene+'"></div><div class="notice" style="margin-top:12px">保存当前标签组合，并在知识抽取阶段独立配置字段。</div>','创建',()=>toast('文档集已创建'));
  if(a==='finish-intake'){markDone('intake');toast('文档集已保存');return go('parse')}
  if(a==='review-raw'){state.knowledgeMode='raw';state.directKnowledgeSet=true;state.dualPath=false;state.reviewScope='raw';state.approvalScope='raw';state.certificationScope='raw';state.consumptionSource='raw';state.approved=false;state.certified=false;markDone('parse');toast('已跳过知识抽取，进入原始知识审核');return go('review')}
  if(a==='start-extraction'||a==='finish-parse'){state.knowledgeMode='raw-structured';state.directKnowledgeSet=false;state.dualPath=true;state.reviewScope='raw';state.approvalScope='raw';state.certificationScope='raw';state.consumptionSource='both';state.approved=false;state.certified=false;markDone('parse');toast('已选择知识抽取，后续将同时审核两类知识');return go('extract')}
  if(a==='continue-structured'){state.knowledgeMode='raw-structured';state.directKnowledgeSet=false;state.dualPath=true;state.reviewScope='structured';state.approved=false;state.certified=false;state.consumptionSource='both';toast('已进入结构化知识抽取');return go('extract')}
  if(a==='run-parse')return toast('多模态解析已启动');
  if(a==='preview-parse')return modal('解析预览','<div class="evidence">已识别正文、表格和图表；页面坐标与原文证据已保留。</div>','关闭');
  if(a==='finish-parse'){markDone('parse');toast('质量准入完成');return go('extract')}
  if(a==='copy-schema')return toast('字段配置已复制，可独立调整');
  if(a==='add-field')return modal('添加抽取字段','<div class="form-field"><label>字段名称</label><input id="new-field" value="影响等级"></div>','添加',()=>{const v=$('#new-field')?.value||'影响等级';state.fields[state.selectedSet].push(v);render()});
  if(a==='remove-field'){state.fields[state.selectedSet]=state.fields[state.selectedSet].filter(x=>x!==el.dataset.field);return render()}
  if(a==='run-extract')return toast('已生成 12 条结构化知识');
  if(a==='create-model')return modal('新建知识模型','<div class="form-grid"><div class="form-field"><label>模型名称</label><input value="经营诊断结论"></div><div class="form-field"><label>模型表标识</label><input value="operation_diagnosis"></div><div class="form-field full"><label>模型说明</label><textarea>定义经营问题诊断结论及其证据、原因与建议</textarea></div></div>','创建模型',()=>toast('知识模型表已创建'));
  if(a==='config-enum-values'){const field=el.dataset.field,values=sceneEnumOptions[field]||['影响','驱动','归属'];return modal(`${field} · 枚举值配置`,`<div class="notice">枚举值将用于知识结构校验，并在抽取任务的“用户填写”字段中生成下拉选项。</div><div class="enum-config-list">${values.map((x,i)=>`<label><span>⋮⋮</span><input value="${x}"><button ${i<2?'disabled':''}>×</button></label>`).join('')}<button class="btn small">＋ 添加枚举值</button></div>`,'保存枚举值',()=>toast(`${field}枚举值已保存`))}
  if(a==='add-model-field'||a==='edit-model-field')return modal(a==='add-model-field'?'添加模型字段':'编辑模型字段','<div class="form-grid"><div class="form-field"><label>字段名称</label><input value="影响等级"></div><div class="form-field"><label>字段类型</label><select><option>文本</option><option>枚举</option></select></div><div class="form-field"><label>取值方式</label><select><option>自动抽取</option><option>用户填写</option><option>文档自身标签</option><option>场景标签</option></select></div><div class="form-field"><label>标签映射 / 抽取要求</label><input value="从正文判断影响等级"></div></div>','保存字段',()=>toast('模型字段已保存'));
  if(a==='save-model')return toast('知识模型结构已保存');
  if(a==='save-extract-task')return toast(`抽取任务已保存：${state.extractDocs.size} 个文档，${state.taskModels.size} 个知识结构`);
  if(a==='add-task-docs')return modal('从知识集添加文档',`<div class="search"><span>⌕</span><input placeholder="搜索知识标题、内容或标签"></div><div class="task-doc-picker">${demoDocs.map(x=>`<label><input type="checkbox" ${state.extractDocs.has(x.id)?'checked':''}><span><b>${x.name}</b><small>${x.source} · ${x.tags.slice(0,3).join(' / ')}</small></span></label>`).join('')}</div>`,'添加所选文档',()=>{state.extractDocs.add(4);toast('已添加所选文档');render()});
  if(a==='clear-task-docs'){state.extractDocs.clear();toast('已清空任务文档');return render()}
  if(a==='run-extract-task'){state.knowledgeMode='raw-structured';state.directKnowledgeSet=false;state.dualPath=true;state.reviewScope='raw';markDone('extract');toast(`抽取完成：生成结构化知识，并保留 ${state.extractDocs.size} 个原始文档进入联合审核`);return go('review')}
  if(a==='finish-extract'){state.knowledgeMode='raw-structured';state.directKnowledgeSet=false;state.dualPath=true;state.reviewScope='raw';markDone('extract');toast('抽取完成，请分别审核原始知识与抽取后知识');return go('review')}
  if(a==='clear-review-filters'){document.querySelectorAll('[data-review-filter]').forEach(x=>{if(x.tagName==='SELECT'){[...x.options].forEach((o,i)=>o.selected=i===0)}else x.value=''});applyReviewFilters();return toast('筛选条件已清空')}
  if(a==='preview-evidence')return modal('原文证据定位',`<div class="evidence"><b>${domain().samples.docs[0]}</b><p>系统已定位到第 18 页对应段落，并保留原文页码、坐标与抽取规则版本。</p><mark>当前知识字段可逐项回溯至原文证据。</mark></div>`,'关闭');
  if(a==='add-record')return modal('人工补录知识','<div class="form-field"><label>知识名称</label><input placeholder="请输入"></div><div class="form-field" style="margin-top:12px"><label>来源与说明</label><textarea></textarea></div>','保存',()=>toast('知识已补录'));
  if(a==='batch-confirm')return toast('已确认 9 条高置信知识');
  if(a==='drop-record')return toast('该条知识已放弃并记录原因');
  if(a==='save-record')return toast('修改已保存并留痕');
  if(a==='confirm-record'){if(state.route==='review'){const target=el?.dataset?.recordId||state.reviewRecord;const item=(reviewResults[state.reviewModel]||[]).find(x=>x.id===target);if(item)item.status='已确认'}else{const item=records.find(x=>x.id===state.selectedRecord);if(item)item.status='已确认'}toast('知识已确认');return render()}
  if(a==='submit-approval'){markDone('review');state.approvalWorkItem=null;toast('已提交领域知识责任人');return go('approval')}
  if(a==='reject-owner')return toast('知识包已退回专家修订');
  if(a==='approve-owner'){state.approved=true;state.certificationWorkItem=null;markDone('approval');toast('审批通过，已流转专委会认证');return go('certification')}
  if(a==='domain-only'){state.certified=true;state.rawPackageCertified=true;if(state.knowledgeMode==='raw-structured')state.structuredPackageCertified=true;markDone('certification');toast('已定性为领域级知识，可进入知识服务构建');return render()}
  if(a==='certify'){state.certified=true;markDone('certification');state.rawPackageCertified=true;if(state.knowledgeMode==='raw-structured'){state.structuredPackageCertified=true;state.consumptionSource='both';toast('原始知识包与结构化知识包均已认证，可分别或组合构建服务')}else{state.structuredPackageCertified=false;state.consumptionSource='raw';toast('原始知识包已认证，可选择任意知识服务模式')}return render()}
  if(a==='publish-service'){if(!state.selectedBases.size)return toast('请至少选择一个已发布知识库');state.built=true;state.published=true;markDone('service');toast(`${serviceTypes[state.serviceMode].name}已构建并发布`);return render()}
  if(a==='test-service')return toast('检索测试完成：命中 1 条可信知识');
  if(a==='copy-endpoint')return toast('调用地址已复制');
}
function intakeV2(){return intake().replace(' <small>8 条管道</small>','').replace(' <small>多格式文档</small>','')}
function scenarioTagRuleCard(){return `<div class="rule-card enabled scenario-tag-rule"><div><span class="rule-icon">◇</span><b>场景化标签配置</b><small>维护知识集可用的标签维度和枚举值</small></div><span class="status ok">已配置</span><p>责任中心 / 业务域 / 对象 / 主题 / 适用区域 · 共 15 个枚举值</p><button class="btn small" data-action="config-scenario-tags">配置标签</button></div>`}
function setBuildPanelV2(){return setBuildPanel().replace('class="rule-grid"','class="rule-grid rule-grid-three"').replace('</button></div></div><div class="schedule-bar">',`</button></div>${scenarioTagRuleCard()}</div><div class="schedule-bar">`)}
function intakeV3(){const d=domain();if(!['integration','set'].includes(state.intakeTab))state.intakeTab='set';const tabs=[['integration','知识集成','系统集成与离线上传'],['set','知识集构建','自动规则、质量过滤与场景标签']];return `${context()}${pageHead('STAGE 01 · 领域知识管理员','知识接入',`在“${d.name}”领域完成知识集成，并在知识集构建过程中配置质量与场景标签。`,'<button class="btn">接入日志</button>')}<div class="intake-tabs two-step">${tabs.map((x,i)=>`<button class="intake-tab ${state.intakeTab===x[0]?'active':''}" data-intake-tab="${x[0]}"><span>${i+1}</span><b>${x[1]}</b><small>${x[2]}</small></button>`).join('')}</div>${state.intakeTab==='integration'?`<div class="integration-switch"><button class="${state.integrationMode==='system'?'active':''}" data-integration-mode="system">系统集成</button><button class="${state.integrationMode==='offline'?'active':''}" data-integration-mode="offline">离线上传</button></div>${integrationPanel()}`:setBuildPanelV2()}<div class="action-bar"><span class="notice">知识集每日 00:00 自动执行规则添加与质量检查；场景标签支持对知识集内容单条或批量应用。</span><span class="spacer"></span><button class="btn primary" data-action="finish-intake">完成知识接入并进入解析 →</button></div>`}
function intakeV4(){const d=domain();if(!['integration','set'].includes(state.intakeTab))state.intakeTab='integration';const isIntegration=state.intakeTab==='integration';return `${context()}${pageHead('STAGE 01 · 领域知识管理员',isIntegration?'知识集成':'知识集构建',isIntegration?`在“${d.name}”领域查看系统内置知识管道，或通过离线上传创建知识。`:`从已接入知识构建知识集，配置自动添加、质量过滤和场景化标签。`,'<button class="btn">接入日志</button>')}${isIntegration?`<div class="integration-switch"><button class="${state.integrationMode==='system'?'active':''}" data-integration-mode="system">系统集成</button><button class="${state.integrationMode==='offline'?'active':''}" data-integration-mode="offline">离线上传</button></div>${integrationPanel()}`:setBuildPanelV2()}<div class="action-bar"><span class="notice">${isIntegration?'完成知识来源接入后，进入知识集构建并配置自动规则、质量与场景标签。':'知识集构建完成后统一进入多模态解析与质量准入，再选择原文或结构化知识路径。'}</span><span class="spacer"></span><button class="btn primary" data-action="${isIntegration?'go-set-build':'finish-intake'}">${isIntegration?'下一步：进入知识集构建 →':'完成知识集构建并进入多模态解析 →'}</button></div>`}
function parseV2(){return parse().replace('<div class="action-bar"><span class="spacer"></span><button class="btn primary" data-action="finish-parse">确认准入并配置抽取 →</button></div>',`<div class="knowledge-route-selector"><div class="route-selector-head"><span>⇄</span><div><b>解析完成后选择知识生产路径</b><small>同一场景可只消费一种知识包，也可让原始文档和结构化知识两条路径都完成审核认证。</small></div></div><div class="route-selector-grid"><section><em>完整路径 · 1-2-3-4-5-6-7</em><b>结构化知识包</b><p>继续知识抽取与专家审核，形成结构化知识后审批、认证并构建服务。</p><button class="btn" data-action="finish-parse">继续结构化加工 →</button></section><section><em>快捷路径 · 1-2-5-6-7</em><b>原始文档知识包</b><p>跳过结构化抽取，以解析后的原文、标签和证据直接完成审批认证。</p><button class="btn" data-action="submit-raw-approval">原始文档提交审批 →</button></section><section class="recommended"><em>组合路径 · 两类知识并行</em><b>原文 + 结构化知识</b><p>先认证原文知识包，再继续抽取形成结构化知识包，最终按场景融合消费。</p><button class="btn primary" data-action="start-dual-path">两条路径并行推进 →</button></section></div></div>`)}
function parseV3(){return parse().replace('<div class="action-bar"><span class="spacer"></span><button class="btn primary" data-action="finish-parse">确认准入并配置抽取 →</button></div>',`<div class="knowledge-route-selector extraction-decision"><div class="route-selector-head"><span>⇄</span><div><b>解析完成后，选择是否需要知识抽取</b><small>无论是否抽取，解析后的原始知识 / 文档都必须先完成知识审核、审批与认证。</small></div></div><div class="route-selector-grid two-options"><section><em>跳过抽取 · 1-2-4-5-6-7</em><b>直接审核原始知识</b><p>以多模态解析后的原始知识、文档内容、标签和证据进入审核，最终形成一个原始知识认证包。</p><button class="btn" data-action="review-raw">不需要抽取，进入知识审核 →</button></section><section class="recommended"><em>执行抽取 · 1-2-3-4-5-6-7</em><b>生成并审核两类知识</b><p>对原始知识进一步抽取形成新知识；后续同时审核、审批和认证原始知识与抽取后知识，形成两个认证知识包。</p><button class="btn primary" data-action="start-extraction">需要抽取，配置抽取任务 →</button></section></div><div class="route-decision-note"><span>原始知识 / 文档</span><i>始终进入审核认证</i><b>＋</b><span>抽取后知识</span><i>仅在执行抽取时产生</i></div></div>`)}
function auditDirectory(){return `<aside class="audit-directory"><div class="audit-directory-title"><span><b>知识目录</b><small>3级目录 · 标签映射</small></span><button data-action="configure-audit-view">⚙</button></div><div class="directory-level-legend"><span>L1 责任中心</span><span>L2 业务域</span><span>L3 对象</span></div><div class="audit-tree-search"><span>⌕</span><input placeholder="搜索知识目录"></div><div class="audit-tree"><div class="tree-node level-1 active"><span>▾</span><small>L1 · 责任中心</small><b>区域TOB</b><em>30</em></div><div class="tree-node level-2 active"><span>▾</span><small>L2 · 业务域</small><b>政企</b><em>20</em></div><div class="tree-node level-3 selected"><span></span><small>L3 · 对象</small><b>渠道</b><em>12</em></div></div></aside>`}
function auditTagFilters(){return `<div class="audit-filter-panel"><div class="audit-filter-row"><b>责任中心</b>${['区域TOB','集团财经','子公司经营部'].map((x,i)=>`<button class="audit-filter-chip ${i===0?'active':''}">${x}</button>`).join('')}</div><div class="audit-filter-row"><b>业务域</b>${['经营管理','账务核算','资金运营'].map((x,i)=>`<button class="audit-filter-chip ${i===0?'active':''}">${x}</button>`).join('')}</div><div class="audit-filter-row"><b>对象</b>${['渠道','经营单元','客户群','产品线'].map((x,i)=>`<button class="audit-filter-chip ${i===0?'active':''}">${x}</button>`).join('')}</div><div class="audit-filter-row"><b>主题</b>${['收入预警','盈利改善','库存周转','经营目标'].map((x,i)=>`<button class="audit-filter-chip ${i<2?'active':''}">${x}</button>`).join('')}</div><div class="audit-filter-row"><b>适用区域</b>${['中国区','海外','全球'].map((x,i)=>`<button class="audit-filter-chip ${i===0?'active':''}">${x}</button>`).join('')}</div></div>`}
function auditStatus(index,item){return item.status==='已确认'?'已审核':index===1?'已审核':index===2?'人工新增':'AI 待确认'}
function reviewAuditFilters(){return `<section class="panel review-list-filter"><div class="panel-head"><div><h3>筛选字段</h3><small>仅按主题和适用区域筛选当前知识结构的结果</small></div><button class="btn small" data-action="clear-review-filters">清空筛选</button></div><div class="review-list-filter-grid"><div class="form-field"><label>主题</label><select data-review-filter="主题"><option value="">全部主题</option>${sceneEnumOptions['主题'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="form-field"><label>适用区域</label><select data-review-filter="适用区域"><option value="">全部区域</option>${sceneEnumOptions['适用区域'].map(x=>`<option>${x}</option>`).join('')}</select></div><span id="review-filter-count">当前显示全部结果</span></div></section>`}
function openReviewRecordDialog(id){const model=knowledgeModels.find(x=>x.id===state.reviewModel)||knowledgeModels[0],record=(reviewResults[model.id]||[]).find(x=>x.id===id);if(!record)return;state.reviewRecord=id;modal(`${model.name} · 查看 / 修改`,`<div class="review-record-modal"><div class="review-form-hint"><span>▦</span><div><b>${record.values['知识标题']}</b><small>结果编号 ${record.id} · 字段随“${model.name}”知识结构呈现</small></div><span class="confidence-pill">置信度 ${record.confidence}%</span></div><div class="form-grid review-form-grid">${model.fields.map(x=>reviewFieldControl(x,record.values[x[0]])).join('')}</div><div class="evidence review-evidence"><b>来源证据</b><span>${domain().samples.docs[0]} · 原文定位第 18 页</span><mark>${record.values['规则逻辑']||record.values['问题描述']||record.values['驱动因素']||'已关联原文证据'}</mark></div></div>`,'保存修改',()=>toast('修改已保存并留痕'))}
function reviewPage(){
  const model=knowledgeModels.find(x=>x.id===state.reviewModel)||knowledgeModels[0],results=reviewResults[model.id]||[];
  return `${context()}${pageHead('STAGE 04 · 领域知识专家','知识审核','通过知识目录定位范围，仅使用主题和适用区域筛选；查看或修改时再打开对应知识结构表单。','<button class="btn" data-action="add-record">＋ 新增知识</button>')}<div class="audit-shell review-list-only">${auditDirectory()}<main class="audit-main">${reviewAuditFilters()}<section class="panel review-list-panel"><div class="panel-head"><div><h3>知识列表</h3><small>选择知识结构查看对应抽取结果</small></div><div class="review-list-tools"><div class="audit-type-tabs">${knowledgeModels.map(x=>`<button class="${x.id===model.id?'active':''}" data-review-model="${x.id}"><b>${x.name}</b><span>${(reviewResults[x.id]||[]).length}</span></button>`).join('')}</div><button class="btn small" data-action="batch-confirm">批量确认</button></div></div><div class="audit-table-wrap"><table class="audit-table review-compact-table"><thead><tr><th><input type="checkbox"></th><th>知识编码</th><th>知识类型</th><th>知识名称</th><th>主题</th><th>适用区域</th><th>状态</th><th>知识来源</th><th>操作</th></tr></thead><tbody>${results.map((x,i)=>`<tr data-review-values="${esc(JSON.stringify(x.values))}"><td><input type="checkbox"></td><td><code>${x.id}</code></td><td>${model.name}</td><td><b>${x.values['知识标题']}</b></td><td>${x.values['主题']||domain().topic}</td><td>${x.values['适用区域']||domain().region}</td><td>${badge(auditStatus(i,x))}</td><td><button class="source-link" data-action="preview-evidence">${domain().samples.docs[i%domain().samples.docs.length]}</button></td><td><div class="row-actions"><button data-review-result="${x.id}">查看 / 修改</button><button data-action="confirm-record" data-record-id="${x.id}">确认</button><button class="danger" data-action="drop-record">删除</button></div></td></tr>`).join('')}</tbody></table><div class="review-empty">没有符合当前筛选条件的知识</div></div><div class="audit-table-footer"><span>共 ${results.length} 条知识</span><span>已选 0 条</span><div><button>‹</button><b>1</b><button>›</button></div></div></section></main></div><div class="action-bar"><span class="notice">审核完成后形成知识包，提交领域知识责任人进行独立审批。</span><span class="spacer"></span><button class="btn primary" data-action="submit-approval">提交知识审批 →</button></div>`;
}
function certificationV2(){
  const rows=Object.entries(reviewResults).flatMap(([model,items])=>items.map((x,i)=>({...x,model:knowledgeModels.find(m=>m.id===model)?.name||model,index:i})));
  return `${pageHead('STAGE 06 · 领域专委会责任人','知识认证','领域专委会在完整知识清单上进行组织价值、复用范围与治理风险评估，最终定性组织级知识。','<button class="btn" data-action="configure-audit-view">⚙ 页面配置</button>')}${governanceRoleBanner('06','知识认证','领域专委会责任人','最终定性知识是否能够成为组织级知识',state.certified?'组织级知识':'待认证')}<div class="audit-shell certification-audit">${auditDirectory()}<main class="audit-main">${auditTagFilters()}<div class="audit-toolbar"><div class="audit-type-tabs"><button class="active"><b>待认证</b><span>9</span></button><button><b>组织级知识</b><span>68</span></button><button><b>领域级知识</b><span>12</span></button></div><div class="audit-toolbar-actions"><div class="search"><span>⌕</span><input placeholder="搜索知识名称或编码"></div></div></div><div class="audit-table-wrap"><table class="audit-table certification-table"><thead><tr><th><input type="checkbox"></th><th>知识编码</th><th>知识类型</th><th>知识名称</th><th>责任中心</th><th>业务域</th><th>对象</th><th>主题</th><th>适用区域</th><th>审批状态</th><th>知识来源</th><th>操作</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td><input type="checkbox" ${i<3?'checked':''}></td><td><code>${x.id}</code></td><td>${x.model}</td><td><b>${x.values['知识标题']}</b></td><td>${x.values['责任中心']||'区域TOB'}</td><td>${x.values['业务域']||domain().name}</td><td>${x.values['对象']||domain().object}</td><td>${x.values['主题']||domain().topic}</td><td>${x.values['适用区域']||domain().region}</td><td>${badge('审批通过')}</td><td><button class="source-link" data-action="preview-evidence">${domain().samples.docs[i%4]}</button></td><td><button class="btn small" data-action="preview-evidence">查看证据</button></td></tr>`).join('')}</tbody></table></div><div class="audit-table-footer"><span>共 ${rows.length} 条待认证知识</span><span>已选 3 条</span><div><button>‹</button><b>1</b><button>›</button></div></div></main></div><div class="certification-decision"><div><span>ORGANIZATION KNOWLEDGE CERTIFICATION</span><h3>专委会认证意见</h3><p>所选知识来源可信、适用边界清晰，具备跨团队复用价值。</p></div><div class="certification-score"><span><b>组织价值</b><em>高</em></span><span><b>复用范围</b><em>广</em></span><span><b>证据可信</b><em>100%</em></span><span><b>治理风险</b><em>低</em></span></div><div class="certification-actions">${state.certified?`<button class="btn primary" data-route="service">${state.rawPackageCertified?'构建双知识包服务 →':'构建知识服务 →'}</button>`:'<button class="btn" data-action="domain-only">保留为领域级</button><button class="btn primary" data-action="certify">认证为组织级知识</button>'}</div></div>`;
}
function directFlowBanner(stage){return `<div class="direct-flow-banner"><span>⌁</span><div><b>原始文档知识包 · ${stage}</b><small>文档已完成多模态解析、质量准入和场景标签配置，无需知识抽取与专家审核。</small></div><em>路径 1-2-5-6-7</em></div>`}
function approvalDirect(){const items=offlineKnowledge.slice(0,4);return `${context()}${pageHead('STAGE 05 · 领域知识责任人','知识审批','领域知识责任人直接审批已完成质量检查的知识集；审批通过后流转领域专委会认证。','<button class="btn">查看质量报告</button>')}${governanceRoleBanner('05','知识审批','领域知识责任人','判断知识集整体是否准确、适用且可用于知识服务',state.approved?'已审批':'待审批')}${directFlowBanner('审批')}<div class="governance-grid"><section class="panel"><div class="panel-head"><div><h3>知识集审批检查项</h3><small>${domain().name}知识集 V1.0 · 30 条知识</small></div><span class="status info">知识集整体审批</span></div><div class="panel-body approval-checks">${[['来源合规','知识均来自已授权管道或用户上传','已通过'],['质量准入','规则与 AI 质量检查均达到阈值','已通过'],['标签完整','责任中心、业务域等标签满足准入要求','已通过'],['适用范围','知识集服务范围与访问边界清晰','待确认']].map((x,i)=>`<label class="approval-check"><input type="checkbox" ${i<3?'checked':''}><span><b>${x[0]}</b><small>${x[1]}</small></span><em class="${i<3?'done':''}">${x[2]}</em></label>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h3>知识集摘要</h3><small>来源、质量与标签覆盖</small></div>${badge('质量检查通过')}</div><div class="panel-body"><div class="governance-metrics"><span><small>知识文档</small><b>30</b></span><span><small>质量通过率</small><b>93%</b></span><span><small>标签覆盖率</small><b>86%</b></span></div><div class="approval-source"><b>系统准入结论</b><p>知识集已按每日任务完成自动添加、规则判断与 AI 质量检查，可直接进入文档级知识服务构建。</p><small>知识底座 · 今天 00:00 自动执行</small></div></div></section></div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>知识集内容抽样</h3><small>审批结论将应用于整个知识集</small></div><span class="status warn">${items.length} 条抽样展示</span></div><table class="data-table"><thead><tr><th>知识标题</th><th>类型</th><th>来源</th><th>场景标签</th><th>质量分</th><th>原文</th></tr></thead><tbody>${items.map((x,i)=>`<tr><td><b>${x.title}</b></td><td>${x.type}</td><td>${demoDocs[i]?.source||'知识圈'}</td><td><div class="tag-row"><span class="tag">${domain().name}</span><span class="tag">${domain().topic}</span></div></td><td>${[96,92,89,87][i]}</td><td><button class="btn small" data-action="preview-evidence">查看</button></td></tr>`).join('')}</tbody></table></section><div class="action-bar"><button class="btn danger" data-action="reject-owner">退回知识集构建</button><span class="spacer"></span><button class="btn success" data-action="approve-owner">审批通过并提交认证 →</button></div>`}
function certificationDirect(){const items=offlineKnowledge.slice(0,4);return `${context()}${pageHead('STAGE 06 · 领域专委会责任人','知识认证','领域专委会对已审批知识集进行最终定性；认证后可直接构建服务，也可继续结构化抽取。','<button class="btn">认证规则</button>')}${governanceRoleBanner('06','知识认证','领域专委会责任人','最终定性知识集是否具备组织级复用价值',state.certified?'组织级知识集':'待认证')}${directFlowBanner('认证')}<div class="certification-hero"><div><span>ORGANIZATION KNOWLEDGE SET CERTIFICATION</span><h2>${domain().name}原始文档知识包 V1.0</h2><p>责任人审批已通过，当前以完整文档及场景标签为知识载体；认证后仍可继续抽取形成结构化知识。</p></div><div class="certification-seal ${state.certified?'done':''}"><span>${state.certified?'✓':'委'}</span><b>${state.certified?'已认证':'待定性'}</b></div></div><div class="certification-grid">${[['组织价值','沉淀跨团队可共享的领域文档与实践材料','高'],['服务适配','适合切片向量化与语义检索服务','语义'],['来源可信','全部文档可回溯至原始知识来源','100%'],['治理风险','权限、区域及失效范围均已配置','低']].map((x,i)=>`<section><span class="cert-icon">${['◆','⌁','◎','◇'][i]}</span><small>${x[0]}</small><b>${x[2]}</b><p>${x[1]}</p></section>`).join('')}</div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>认证知识集清单</h3><small>知识集整体认证，保留每条文档的来源与标签</small></div>${badge(state.certified?'已认证':'审批通过')}</div><table class="data-table"><thead><tr><th>知识标题</th><th>类型</th><th>来源</th><th>责任中心</th><th>业务域</th><th>适用区域</th></tr></thead><tbody>${items.map((x,i)=>`<tr><td><b>${x.title}</b></td><td>${x.type}</td><td>${demoDocs[i]?.source||'知识圈'}</td><td>区域TOB</td><td>${domain().name}</td><td>${domain().region}</td></tr>`).join('')}</tbody></table></section><div class="certification-decision"><div><span>KNOWLEDGE SET CERTIFICATION</span><h3>专委会认证意见</h3><p>知识集来源可信、质量达标，可直接构建服务，也可保留认证结果后继续结构化加工。</p></div><div class="certification-score"><span><b>组织价值</b><em>高</em></span><span><b>复用范围</b><em>广</em></span><span><b>来源可信</b><em>100%</em></span><span><b>治理风险</b><em>低</em></span></div><div class="certification-actions">${state.certified?'<button class="btn" data-route="service">构建原文知识服务</button><button class="btn primary" data-action="continue-structured">继续结构化抽取 →</button>':'<button class="btn" data-action="domain-only">保留为领域级</button><button class="btn primary" data-action="certify">认证为组织级知识集</button>'}</div></div>`}
function serviceSourceSelector(){const raw=state.rawPackageCertified||state.directKnowledgeSet,structured=state.structuredPackageCertified||(!state.rawPackageCertified&&!state.directKnowledgeSet),both=raw&&structured;const option=(id,icon,title,desc,enabled)=>`<button class="source-package ${state.consumptionSource===id?'active':''}" data-consumption-source="${id}" ${enabled?'':'disabled'}><span>${icon}</span><div><b>${title}</b><small>${desc}</small></div><em>${enabled?'可消费':'待认证'}</em></button>`;return `<section class="service-source-selector"><div><span>KNOWLEDGE CONSUMPTION SOURCE</span><h3>选择当前场景消费的知识包</h3><p>一个场景可以只消费一种知识，也可以融合原始文档与结构化知识。</p></div><div class="source-package-grid">${option('raw','▤','原始文档知识包','全文切片 / 语义检索 / 原文证据',raw)}${option('structured','◇','结构化知识包','精确字段 / 知识图谱 / 规则消费',structured)}${option('both','✣','双知识包融合','语义召回 + 结构化精排 + 双重证据',both)}</div></section>`}
function serviceV2(){let html=service().replace('STAGE 06 · 领域知识管理员 / IT','STAGE 07 · 领域知识管理员 / IT');if(state.route==='storage')html=html.replace('正式入库与知识服务构建','知识入库').replace('审批后的知识在此生成正式版本，并按消费需求构建语义、精确或混合检索服务。','将已认证知识生成正式版本并写入知识底座，保留来源证据、审批记录与版本关系。');else html=html.replace('正式入库与知识服务构建','检索服务构建').replace('审批后的知识在此生成正式版本，并按消费需求构建语义、精确或混合检索服务。','根据当前场景选择原始文档知识包、结构化知识包或双知识包融合，构建对应的检索消费服务。');html=html.replace('<div class="service-modes">',serviceSourceSelector()+'<div class="service-modes">');if(state.consumptionSource==='raw')html=html.replace(`${domain().scene}知识包 V1.0 · 12 条`,`${domain().name}原始文档知识包 V1.0 · 30 条`).replace('data-mode="graph"','data-mode="graph" disabled title="知识图谱服务需先完成结构化加工"').replace('语义召回候选知识，再用领域标签与图谱关系精排','语义召回候选知识，再用场景标签进行精确过滤');if(state.consumptionSource==='both')html=html.replace(`${domain().scene}知识包 V1.0 · 12 条`,`${domain().name}双知识包 · 42 条`).replace('基于正式知识版本','基于原始文档与结构化知识版本');return html}
function packageTabs(kind,current){const attr=`data-${kind}-scope`;const options=[['raw','▤','原始知识 / 文档','多模态解析结果',offlineKnowledge.length],['structured','◇','抽取后知识','知识模型抽取结果',Object.values(reviewResults).flat().length]];return `<div class="knowledge-package-tabs">${options.filter(x=>x[0]==='raw'||state.knowledgeMode==='raw-structured').map(x=>`<button class="${current===x[0]?'active':''}" ${attr}="${x[0]}"><span>${x[1]}</span><div><b>${x[2]}</b><small>${x[3]}</small></div><em>${x[4]} 条</em></button>`).join('')}</div>`}
function rawKnowledgeTable(actionLabel='查看 / 修改'){return `<div class="audit-table-wrap"><table class="audit-table review-compact-table"><thead><tr><th><input type="checkbox"></th><th>知识编码</th><th>知识形态</th><th>知识标题</th><th>主题</th><th>适用区域</th><th>状态</th><th>知识来源</th><th>操作</th></tr></thead><tbody>${offlineKnowledge.map((x,i)=>`<tr data-review-values="${esc(JSON.stringify({'主题':domain().topic,'适用区域':domain().region}))}"><td><input type="checkbox"></td><td><code>R-${String(i+1).padStart(3,'0')}</code></td><td>原始知识 / 文档</td><td><b>${x.title}</b></td><td>${domain().topic}</td><td>${domain().region}</td><td>${badge('待审核')}</td><td>${demoDocs[i]?.source||'离线上传'}</td><td><button class="btn small" data-action="preview-evidence">${actionLabel}</button></td></tr>`).join('')}</tbody></table></div>`}
function structuredKnowledgeTable(){const model=knowledgeModels.find(x=>x.id===state.reviewModel)||knowledgeModels[0],results=reviewResults[model.id]||[];return `<div class="review-list-tools inline-package-tools"><div class="audit-type-tabs">${knowledgeModels.map(x=>`<button class="${x.id===model.id?'active':''}" data-review-model="${x.id}"><b>${x.name}</b><span>${(reviewResults[x.id]||[]).length}</span></button>`).join('')}</div><button class="btn small" data-action="batch-confirm">批量确认</button></div><div class="audit-table-wrap"><table class="audit-table review-compact-table"><thead><tr><th><input type="checkbox"></th><th>知识编码</th><th>知识类型</th><th>知识名称</th><th>主题</th><th>适用区域</th><th>状态</th><th>知识来源</th><th>操作</th></tr></thead><tbody>${results.map((x,i)=>`<tr data-review-values="${esc(JSON.stringify(x.values))}"><td><input type="checkbox"></td><td><code>${x.id}</code></td><td>${model.name}</td><td><b>${x.values['知识标题']}</b></td><td>${x.values['主题']||domain().topic}</td><td>${x.values['适用区域']||domain().region}</td><td>${badge(auditStatus(i,x))}</td><td>${domain().samples.docs[i%domain().samples.docs.length]}</td><td><div class="row-actions"><button data-review-result="${x.id}">查看 / 修改</button><button data-action="confirm-record" data-record-id="${x.id}">确认</button></div></td></tr>`).join('')}</tbody></table></div>`}
function workQueueData(stage){const status={review:'待审核',approval:'待审批',certification:'待认证'}[stage];return [
  {id:'raw-analysis',name:'智能分析知识集',type:'raw',kind:'原始知识集',count:30,source:'知识集构建',owner:'李明',time:'今天 14:20',status},
  {id:'raw-customer',name:'客户经营知识集',type:'raw',kind:'原始知识集',count:18,source:'知识集构建',owner:'周妍',time:'今天 13:45',status},
  {id:'extract-warning',name:'经营预警规则抽取知识集',type:'structured',kind:'抽取知识集',count:9,source:'经营预警抽取任务',owner:'王凯',time:'今天 15:10',status},
  {id:'extract-strategy',name:'经营改进策略抽取知识集',type:'structured',kind:'抽取知识集',count:12,source:'改进策略抽取任务',owner:'陈晨',time:'昨天 18:30',status}
]}
function workQueuePage(stage,title,role,desc){const rows=workQueueData(stage),action={review:'进入审核',approval:'进入审批',certification:'进入认证'}[stage];return `${context()}${pageHead(`STAGE ${{review:'04',approval:'05',certification:'06'}[stage]} · ${role}`,title,desc,'')}<section class="work-queue-summary"><div><span>WAITING WORKSPACE</span><h2>${title}待处理列表</h2><p>先选择一个知识集，再进入该知识集的目录、明细与处理表单。</p></div><div><span><b>${rows.length}</b><small>待处理知识集</small></span><span><b>${rows.filter(x=>x.type==='raw').length}</b><small>原始知识集</small></span><span><b>${rows.filter(x=>x.type==='structured').length}</b><small>抽取知识集</small></span><span><b>${rows.reduce((n,x)=>n+x.count,0)}</b><small>知识总量</small></span></div></section><section class="panel work-queue-panel"><div class="panel-head"><div><h3>待${title.replace('知识','')}知识集</h3><small>名称沿用原知识集名称，或使用创建抽取任务时填写的抽取知识集名称</small></div><div class="work-queue-filters"><select><option>全部知识形态</option><option>原始知识集</option><option>抽取知识集</option></select><div class="search"><span>⌕</span><input placeholder="搜索知识集名称"></div></div></div><div class="table-wrap"><table class="data-table work-queue-table"><thead><tr><th>知识集名称</th><th>知识集形态</th><th>知识数量</th><th>来源 / 任务</th><th>提交人</th><th>提交时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(x=>`<tr><td><div class="queue-set-name"><span class="${x.type}">${x.type==='raw'?'▤':'◇'}</span><div><b>${x.name}</b><small>${x.id.toUpperCase()}</small></div></div></td><td><span class="queue-kind ${x.type}">${x.kind}</span></td><td>${x.count} 条</td><td>${x.source}</td><td>${x.owner}</td><td>${x.time}</td><td>${badge(x.status)}</td><td><button class="btn small primary" data-work-stage="${stage}" data-work-item="${x.id}" data-work-type="${x.type}">${action} →</button></td></tr>`).join('')}</tbody></table></div></section>`}
function reviewV3(){const item=workQueueData('review').find(x=>x.id===state.reviewWorkItem);if(!item)return workQueuePage('review','知识审核','领域知识专家','统一查看待审核的原始知识集与抽取知识集，选择知识集后进入明细审核。');const structured=item.type==='structured';state.reviewScope=item.type;return `${context()}${pageHead('STAGE 04 · 领域知识专家','知识审核',`正在审核“${item.name}”，完成后形成独立知识包并提交领域知识责任人审批。`,`<button class="btn" data-action="back-work-queue">← 返回待审核列表</button><button class="btn" data-action="add-record">＋ 新增知识</button>`)}<div class="selected-work-item"><span class="${item.type}">${structured?'◇':'▤'}</span><div><small>${item.kind}</small><b>${item.name}</b><p>${item.source} · ${item.count} 条知识 · 提交人 ${item.owner}</p></div>${badge('审核中')}</div><div class="audit-shell review-list-only">${auditDirectory()}<main class="audit-main">${reviewAuditFilters()}<section class="panel review-list-panel"><div class="panel-head"><div><h3>${structured?'抽取知识列表':'原始知识 / 文档列表'}</h3><small>${structured?'按知识结构查看并修订抽取结果':'审核内容、标签、来源与原文证据'}</small></div><span class="status info">${item.kind}</span></div>${structured?structuredKnowledgeTable():rawKnowledgeTable()}</section></main></div><div class="action-bar"><span class="notice">当前仅处理“${item.name}”，审核结论将形成该知识集的独立版本。</span><span class="spacer"></span><button class="btn primary" data-action="submit-approval">提交知识审批 →</button></div>`}
function approvalPackageTable(structured){if(!structured)return rawKnowledgeTable('查看');const rows=Object.entries(reviewResults).flatMap(([model,items])=>items.map(x=>({...x,model:knowledgeModels.find(m=>m.id===model)?.name||model})));return `<div class="approval-table-wrap"><table class="data-table"><thead><tr><th>知识编码</th><th>知识类型</th><th>知识名称</th><th>主题</th><th>适用区域</th><th>审核状态</th><th>证据</th></tr></thead><tbody>${rows.map(x=>`<tr><td><code>${x.id}</code></td><td>${x.model}</td><td><b>${x.values['知识标题']}</b></td><td>${x.values['主题']||domain().topic}</td><td>${x.values['适用区域']||domain().region}</td><td>${badge('审核通过')}</td><td><button class="btn small" data-action="preview-evidence">查看</button></td></tr>`).join('')}</tbody></table></div>`}
function approvalV4(){const item=workQueueData('approval').find(x=>x.id===state.approvalWorkItem);if(!item)return workQueuePage('approval','知识审批','领域知识责任人','集中查看专家审核通过的知识集，选择一个知识集后填写审批意见。');const structured=item.type==='structured';state.approvalScope=item.type;return `${context()}${pageHead('STAGE 05 · 领域知识责任人','知识审批',`正在审批“${item.name}”，审批通过后流转领域专委会认证。`,'<button class="btn" data-action="back-work-queue">← 返回待审批列表</button>')}${governanceRoleBanner('05','知识审批','领域知识责任人','审批该知识集的准确性、适用性与业务可用性',state.approved?'已审批':'待审批')}<div class="selected-work-item"><span class="${item.type}">${structured?'◇':'▤'}</span><div><small>${item.kind}</small><b>${item.name}</b><p>${item.source} · ${item.count} 条知识 · 审核已通过</p></div>${badge('审批中')}</div><section class="panel approval-list-panel"><div class="panel-head"><div><h3>待审批${structured?'抽取知识':'原始知识 / 文档'}</h3><small>${item.name}</small></div><span class="status warn">共 ${item.count} 条</span></div>${approvalPackageTable(structured)}</section>${approvalOpinion(!structured)}<div class="action-bar"><button class="btn danger" data-action="reject-owner">退回知识专家</button><span class="spacer"></span><button class="btn success" data-action="approve-owner">审批通过并提交认证 →</button></div>`}
function certificationV3(){const item=workQueueData('certification').find(x=>x.id===state.certificationWorkItem);if(!item)return workQueuePage('certification','知识认证','领域专委会责任人','集中查看审批通过的知识集，选择一个知识集后进行组织级知识定性。');const structured=item.type==='structured';state.certificationScope=item.type;return `${context()}${pageHead('STAGE 06 · 领域专委会责任人','知识认证',`正在认证“${item.name}”，认证结果将形成可独立消费的知识包。`,'<button class="btn" data-action="back-work-queue">← 返回待认证列表</button>')}${governanceRoleBanner('06','知识认证','领域专委会责任人','定性该知识集是否成为组织级知识',state.certified?'认证完成':'待认证')}<div class="selected-work-item"><span class="${item.type}">${structured?'◇':'▤'}</span><div><small>${item.kind}</small><b>${item.name}</b><p>${item.source} · ${item.count} 条知识 · 责任人审批通过</p></div>${badge(state.certified?'已认证':'认证中')}</div><section class="panel approval-list-panel"><div class="panel-head"><div><h3>待认证${structured?'抽取知识':'原始知识 / 文档'}</h3><small>${item.name}</small></div>${badge(state.certified?'已认证':'审批通过')}</div>${approvalPackageTable(structured)}</section><div class="certification-decision"><div><span>ORGANIZATION KNOWLEDGE CERTIFICATION</span><h3>专委会认证意见</h3><p>该知识集来源可信、适用边界清晰，具备跨团队复用价值。</p></div><div class="certification-score"><span><b>组织价值</b><em>高</em></span><span><b>复用范围</b><em>广</em></span><span><b>证据可信</b><em>100%</em></span><span><b>治理风险</b><em>低</em></span></div><div class="certification-actions">${state.certified?'<button class="btn primary" data-route="storage">进入知识入库 →</button>':'<button class="btn" data-action="domain-only">保留为领域级</button><button class="btn primary" data-action="certify">认证为组织级知识</button>'}</div></div>`}
function serviceSourceSelectorV3(){const demo=state.knowledgeMode==='undecided',raw=demo||state.rawPackageCertified||state.knowledgeMode==='raw',structured=demo||state.structuredPackageCertified||state.knowledgeMode==='raw-structured',both=raw&&structured;const option=(id,icon,title,desc,enabled)=>`<button class="source-package ${state.consumptionSource===id?'active':''}" data-consumption-source="${id}" ${enabled?'':'disabled'}><span>${icon}</span><div><b>${title}</b><small>${desc}</small></div><em>${enabled?'可选':'待认证'}</em></button>`;return `<section class="service-source-selector"><div><span>KNOWLEDGE PACKAGE SOURCE</span><h3>先选择服务使用的知识包</h3><p>知识形态与服务模式相互独立；任一认证知识包都可构建切片、图谱或混合模式。</p></div><div class="source-package-grid">${option('raw','▤','原始知识包','可构建：知识切片 / 知识图谱 / 混合模式',raw)}${option('structured','◇','结构化知识包','可构建：知识切片 / 知识图谱 / 混合模式',structured)}${option('both','✣','双知识包组合','可构建：知识切片 / 知识图谱 / 混合模式',both)}</div></section>`}
